(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["moe"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-chunked-prefill-piggyback"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-1\">一 · 事故现场：一次长 prompt 引发的 TPOT 雪崩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-2\">二 · 它约束的是什么：TPOT 上界的可计算化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-3\">三 · 它不解决什么：三条清晰的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-4\">四 · MoE 放大的阻塞：为什么稠密模型上温和的问题在 MoE 上致命</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-5\">五 · 适用边界的工程刻画：什么负载该用它</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-6\">六 · 长 prefill 独占 GPU：一个线上事故与算法的适用边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-7\">七 · 请求入队与 token 级切分：chunk 的诞生点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-8\">八 · 调度器拼批：一个 chunk 加一个解码 batch</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-9\">九 · 合并 batch 走 MoE 路由与分组 GEMM</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-10\">十 · KV 写入：chunk 落页与解码追加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-11\">十一 · 输出解码 token 与请求状态迁移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-12\">十二 · 单步代价的分解与 chunk 取值的工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-13\">十三 · 边界条件：chunk 何时失效，以及每一步的系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-14\">十四 · 单步时间上界的逐项拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-15\">十五 · 为什么 max 会退化成求和：MoE 通信项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-16\">十六 · 调度器伪代码：从队列到拼批</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-17\">十七 · 分组 GEMM 形状碎片的代价与合并路由</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-18\">十八 · KV 页对齐与碎片对并发容量的挤压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-19\">十九 · 与分离式部署的公式对照：省掉的传输项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-20\">二十 · 边界、失效条件与系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-21\">二十一 · 请求形态与长度分布：长短混合是配方的前提</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-22\">二十二 · 并发与批大小：解码队列长度是配方的自变量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-23\">二十三 · SLO 结构：TPOT 严格、TTFT 可放宽</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-24\">二十四 · 负载不对时的三种失败模式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-25\">二十五 · 配方与部署形态的耦合：单池、TP/EP、共享并行策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-26\">二十六 · 负载判据的工程落地：从队列特征到配方选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-27\">二十七 · 硬件档位：按单池拓扑反推卡型与互联预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-28\">二十八 · 并行拓扑：prefill 与解码共享策略的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-29\">二十九 · 量化方案：沿用既有权重/激活方案，不为 piggyback 单独改精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-30\">三十 · KV 策略：chunk 边界与页边界对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-31\">三十一 · 调度参数：chunk 取 SLO 允许的最大值，路由结果合并统计</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-32\">三十二 · 可复现的配置思路：从 SLO 反推，按序定参</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-33\">三十三 · 配方边界：何时该退回分离式部署</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-34\">三十四 · 单步时间预算：chunk 大小如何吃掉 TPOT 余量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-35\">三十五 · 显存与 KV 页碎片：规模上去后第一个崩的地方</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-36\">三十六 · 带宽与通信：All-to-All 把单步时间拉成尖峰</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-37\">三十七 · 功耗与热约束：持续高占用的隐性天花板</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-38\">三十八 · 尾延迟：p99 由最慢的那个 iteration 定义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-39\">三十九 · 规模上限：哪里先触顶的判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-40\">四十 · 规模放大后先崩的那一环：从 chunk 约束到 MoE 分组 GEMM 的 tile 效率</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-41\">四十一 · 精度漂移：合并批次里的数值一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-42\">四十二 · OOM 与 KV 页碎片：chunk 边界不对齐的代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-43\">四十三 · 批抖动与路由不均：MoE 层的形状碎片</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-44\">四十四 · 尾延迟尖刺：All-to-All 与调度抖动的叠加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-45\">四十五 · 监控面与回滚开关</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-46\">四十六 · 失败模式与诊断：从 chunk 边界到 MoE 路由的四个断点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-47\">四十七 · 捎带批次的失效边界：从页碎片到专家形状</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-48\">四十八 · 同族算法的坐标：三条轴上的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-49\">四十九 · 决策表：按约束条件落位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-50\">五十 · 用同一个不等式做跨算法比较</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-51\">五十一 · 具体例子：一条长 prompt 在三种方案下的走向</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-52\">五十二 · 适用条件与规模上限的工程判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-chunked-prefill-piggyback-sec-53\">五十三 · 同族对照：分块捎带在算法谱系中的位置与选用判据</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:482px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 482.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">新请求进入等待队列，按 token 数切分为 chunk</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">调度器每步取一个 prefill chunk 与解码 batch 合并</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">合并后的 batch 走 MoE 路由与分组 GEMM</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">prefill chunk 的 KV 写入分页缓存，解码 token 追加…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">输出解码 token，chunk 完成后请求转入解码队列</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-chunked-prefill-piggyback-sec-1\">一 · 事故现场：一次长 prompt 引发的 TPOT 雪崩</h3>\n<p>某在线对话服务在单池 TP 拓扑上跑连续批处理，解码队列稳定维持数十个请求，TPOT 的 p50 落在个位数毫秒量级。某个时刻一位用户提交了一份长文档摘要请求，prompt 长度远超队列中其余请求的总和。调度器按先到先服务把它整段塞进下一个 iteration：这一次前向里，prefill 部分独占 GPU 数十毫秒，原本该在每步输出的解码 token 全部被推迟。监控上立刻出现一条竖线——TPOT 的 p99 从个位数毫秒跳到数十毫秒，随后几个 iteration 里解码请求的 token 间隔出现尖峰，客户端侧表现为明显的卡顿与重试。</p>\n<p>更糟的是这套服务跑的是 MoE 模型。长 prefill 的 token 在 MoE 层触发大量专家，All-to-All 通信量随被激活的专家数上升；而同一批次里解码 token 的专家分布窄得多。两者混在一个批次里，通信阶段被 prefill 主导，解码 token 只能陪跑等待。阻塞不是一次性的：长 prompt 的 KV 写入分页缓存后，后续若干步的注意力读取模式也发生变化，解码请求的 TPOT 抖动持续了数个调度周期才回落。事故的根因不在硬件，而在调度粒度——一个不可分割的长 prefill 与一批对延迟敏感的解码请求被强行放进同一个前向。</p>\n<p>这个场景定义了本算法要解决的具体问题：<strong>连续批处理中，prefill 与 decode 共享同一前向路径，而 prefill 的计算量正比于 prompt 长度、decode 的计算量正比于批大小，两者量纲不同却争用同一个 iteration 的时间预算。</strong>只要 prefill 不可切分，解码请求的 TPOT 就没有上界，SLO 无法用调度参数表达。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-2\">二 · 它约束的是什么：TPOT 上界的可计算化</h3>\n<p>把问题写成式子，调度器才有可操作的抓手。单个 iteration 的耗时近似为两部分的最大值：</p>\n<div class=\"formula\">$$T_{\\text{iter}} \\approx \\max(T_{\\text{chunk}}, T_{\\text{decode}})$$</div>\n<p>其中 $T_{\\text{chunk}}$ 是单个 prefill chunk 的前向时间，$T_{\\text{decode}}$ 是当前解码 batch 的前向时间。解码请求相邻 token 的间隔就是若干次 $T_{\\text{iter}}$ 的累加，因此 TPOT 的 p99 上界可写成：</p>\n<div class=\"formula\">$$\\text{TPOT}_{\\text{p99}}\\approx \\max_{\\text{iter}}\\left(T_{\\text{decode}}+T_{\\text{chunk}}\\right),\\quad \\text{chunk\\_size}\\le \\frac{\\text{SLO}_{\\text{TPOT}}-T_{\\text{decode}}}{\\text{每 token 时延}}$$</div>\n<p>第二个不等式是本算法的核心工程判断：chunk 的 token 数不是拍脑袋定的，而是由 TPOT SLO 减去解码 batch 自身耗时后剩下的预算，除以每 token 的 prefill 时延反推出来的。这把一个原本靠经验调参的调度问题，变成了一个可以在线求解的约束满足问题。事故中的服务之所以崩，正是因为 chunk_size 等于整个 prompt 长度，右端的不等式被彻底违反。</p>\n<p>代价也随之显式化。chunk 越小，$T_{\\text{chunk}}$ 越小、TPOT 越稳，但 prefill 的有效吞吐下降——每个 chunk 都要重新走一遍权重读取与 MoE 路由，固定开销摊薄不了；同时长 prompt 被切成更多段，首 token 时延 TTFT 被拉长。chunk 越大则相反。这是一个用 TTFT 换 TPOT 稳定性的显式交易，而不是免费午餐。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-3\">三 · 它不解决什么：三条清晰的边界</h3>\n<p>第一条边界是<strong>绝对算力与带宽</strong>。chunk 切分只改变时间在 iteration 之间的分配，不减少总 FLOPs、不减少 KV 缓存写入量、不减少 MoE 的 All-to-All 总量。如果单步前向本身已经逼近显存带宽或 NVLink 带宽上限，切 chunk 只是把同样的总时间摊到更多步上，TPOT 的均值不会变好，只是抖动被压平。它治的是抖动，不是吞吐天花板。</p>\n<p>第二条边界是<strong>并行策略的刚性</strong>。prefill chunk 与解码 token 共享同一前向，意味着两者必须使用同一套 TP/EP 配置。prefill 偏好大 TP 摊薄权重读取、偏好更大的 EP 以容纳专家并行；解码偏好小 TP 降低通信、偏好更紧凑的 EP 布局。piggyback 把这两个偏好锁死在一套配置上，无法各自取最优。这正是它与分离式预填/解码部署的分水岭——后者用跨池 KV 传输与 RDMA 带宽换取两阶段各自的并行自由，而本方法用并行自由度换取零跨池传输。</p>\n<p>第三条边界是<strong>超长上下文的调度开销</strong>。chunk 数随 prompt 长度线性增长，每个 chunk 都要经历一次调度决策、一次 KV 页分配、一次 MoE 路由统计。当上下文长到 chunk 数上百时，调度器自身的 CPU 开销与 KV 页碎片开始侵蚀收益。此外，chunk 边界若与分页 KV 的页边界不对齐，会产生页内碎片，长上下文下 KV 缓存的有效容量下降，反过来挤压可支持的并发 batch 数——这是一个会自我强化的退化路径。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-4\">四 · MoE 放大的阻塞：为什么稠密模型上温和的问题在 MoE 上致命</h3>\n<p>稠密模型里，长 prefill 的阻塞主要来自矩阵乘的时间占用，量级可估、形状规整。MoE 模型多了一层放大：prefill 的 token 数量大、语义分散，路由后几乎命中所有专家，All-to-All 的通信量与专家激活数成正比；解码 token 数量少、语义集中，命中的专家子集窄。两者拼进同一批次后，MoE 层的分组 GEMM 要同时容纳一个宽而碎的 prefill 路由结果和一个窄而集中的解码路由结果。</p>\n<p>后果是 tile 利用率下降。分组 GEMM 的效率依赖每个专家分到的 token 数能填满 tile；prefill chunk 与解码 token 的专家分布不同，合并统计后每个专家的 token 数分布更不均匀，部分专家的分组过小、tile 填不满，单步前向反而被拖慢。事故中观察到的尖峰正是这个机制：不是 prefill 本身慢，而是合并批次把 MoE 层的形状打碎了。工程上的应对是把两者的路由结果合并统计后再做分组，尽量让每个专家的 token 数落在 tile 的整数倍附近；但这只是缓解，形状碎片化的根因是两种负载的语义分布天然不同。</p>\n<p>由此得到一个反直觉的判断：在 MoE 上，chunk 过小不仅拉长 TTFT，还可能因为每步都要重复一次低效的分组 GEMM 而让整体吞吐下降。chunk 大小的下界不由 SLO 单独决定，还受 MoE 分组 GEMM 的最小有效形状约束。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-5\">五 · 适用边界的工程刻画：什么负载该用它</h3>\n<p>把上述分析收拢成可判定的条件。负载侧：请求形态是长短混合的在线对话，批大小由解码队列长度自然决定，SLO 以 TPOT 的 p99 上界为主约束、TTFT 可放宽。这类负载的特征是解码请求持续存在且对间隔敏感，而 prefill 请求偶发且长度方差大——正是 piggyback 收益最大的形态。反过来，若负载以离线批处理为主、TTFT 是硬约束而 TPOT 不敏感，切 chunk 只会无谓地拉长首 token 时延。</p>\n<p>部署侧：单机多卡 TP 或 EP 拓扑，prefill chunk 与解码 token 共享同一前向，KV 使用分页缓存按块写入，chunk 边界与页边界对齐以减少碎片。规模上限受两个因素制约：chunk 切分粒度决定调度开销的下界，MoE 分组 GEMM 效率决定 chunk 大小的下界。当模型规模大到单池 TP/EP 无法容纳、或上下文长到 chunk 数让调度开销不可忽略时，就该转向分离式部署，用跨池传输换并行自由度。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>适合 piggyback</th><th>应转向分离式</th></tr></thead><tbody><tr><td>负载形态</td><td>长短混合在线对话，解码队列常驻</td><td>离线批处理，TTFT 硬约束</td></tr><tr><td>SLO 重心</td><td>TPOT p99 严格，TTFT 可放宽</td><td>TTFT 严格，TPOT 宽松</td></tr><tr><td>并行策略</td><td>单池 TP/EP 可容纳，接受共享配置</td><td>prefill 与 decode 需各自最优 TP/EP</td></tr><tr><td>上下文长度</td><td>chunk 数可控，页碎片可管理</td><td>超长上下文，调度开销与碎片不可忽略</td></tr><tr><td>MoE 形状</td><td>路由合并后分组 GEMM 仍能填满 tile</td><td>专家分布差异导致 tile 利用率持续低下</td></tr></tbody></table>\n<p>最后落到一个具体机制上：调度器在每个 iteration 开始时，先取解码队列长度估算 $T_{\\text{decode}}$，再用 TPOT SLO 减去它得到本步的 prefill 预算，除以实测的每 token prefill 时延，得到本步允许的 chunk token 数，并与 MoE 分组 GEMM 的最小有效形状取较大者。这个取大动作就是适用边界的工程表达——SLO 给出上界，MoE 效率给出下界，两者之间的区间才是 chunk 大小的合法取值域。区间为空时，说明该负载已经越出本方法的边界，应当改换部署形态而不是继续调参。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-6\">六 · 长 prefill 独占 GPU：一个线上事故与算法的适用边界</h3>\n<p>某在线对话服务在午后流量爬升时出现了一次典型的 TPOT 抖动事故：解码队列里已有数十个活跃会话，此时陆续进入若干超长 prompt 请求（文档摘要、代码库问答）。连续批处理调度器按到达顺序把整个 prompt 一次性送进前向，单个长 prefill 独占 GPU 数十毫秒，这段时间内所有解码请求的下一 token 全部被阻塞，用户侧表现为输出卡顿、token 间隔出现尖峰。更糟的是该模型是 MoE 结构，prefill 阶段触发的 All-to-All 通信与解码 batch 的通信需求叠加，阻塞被进一步放大，TPOT 的 p99 直接越过 SLO 红线。运维侧的直觉反应是加机器，但事故的根因不是容量不足，而是调度粒度：只要调度器允许一个不可分割的长 prefill 占据整个 iteration，解码请求就必然被它饿死，加卡只会把事故推迟到更高的负载点。</p>\n<p>分块预填与解码捎带正是针对这一具体问题的解法：把新请求按 token 数切成固定大小的 chunk，每个 iteration 只处理一个 chunk，并把它与当前解码 batch 拼成同一批次一起前向，解码 token 因此每个 iteration 都能推进。抖动上界由此被 chunk 大小硬性约束，可写成 <span class=\"formula\">$$T_{\\text{iter}} \\approx \\max(T_{\\text{chunk}}, T_{\\text{decode}})$$</span>，其中 $T_{\\text{chunk}}$ 为单 chunk 前向时间、$T_{\\text{decode}}$ 为解码 batch 前向时间；调度器据此反推满足 SLO 的最大 chunk token 数，即 <span class=\"formula\">$$\\text{chunk\\_size}\\le \\frac{\\text{SLO}_{\\text{TPOT}}-T_{\\text{decode}}}{\\text{每 token 时延}}$$</span>。这个公式同时划出了方法的边界：它约束的是 TPOT，不是 TTFT。chunk 越小，单步越短、TPOT 越稳，但 prefill 的有效吞吐越低，长 prompt 的首 token 时延被拉长且排队时间随负载不可控——事故里的长 prompt 用户从“卡住别人”变成“自己被卡住”，这是同一枚硬币的两面。</p>\n<p>因此适用边界必须写清楚。它适合中低负载、单池部署、TPOT 的 p99 严格但 TTFT 可放宽的场景；不适合 TTFT 本身就是硬 SLO 的交互式场景（如首屏补全、语音助手），也不适合已经接近 GPU 饱和的高负载段——此时 chunk 切分带来的调度开销与碎片会吃掉本就不多的余量。与分离式预填/解码部署相比，本方法不需要跨池 KV 传输与 RDMA 带宽，在低负载下 GPU 利用率更高；代价是两阶段共享同一套并行策略，prefill 与解码无法各自采用最优的 TP/EP 配置，MoE 场景下这一约束尤其明显。规模上限受 chunk 切分粒度与 MoE 分组 GEMM 效率制约：超长上下文使 chunk 数增多，调度开销与 KV 页碎片同步上升。</p>\n<p>失效条件可以归为三类，工程上应逐项设防。其一是 chunk 切得过小：prefill 吞吐明显下降，TTFT 被拉长到超出首 token SLO，长 prompt 请求排队时间失控——对策是取 SLO 允许的最大 chunk，而不是盲目求小。其二是 MoE 层的形状碎片：prefill chunk 与解码 token 的专家分布差异大，合并批次后分组 GEMM 形状更碎，tile 利用率下降反而拖慢单步前向，抵消了捎带带来的收益；对策是把两者的路由结果合并统计后再分组，避免按来源各自成组。其三是 KV 分页碎片：chunk 边界与页边界不对齐时产生页内碎片，长上下文下 KV 缓存有效容量下降，挤压可支持的并发 batch；对策是让 chunk 边界与页边界对齐。下表给出三种典型负载下的判断：</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>TPOT 约束</th><th>TTFT 约束</th><th>本方法是否适用</th></tr></thead><tbody><tr><td>长短混合在线对话，中低负载</td><td>p99 严格</td><td>可放宽</td><td>适用，chunk 按 SLO 反推取最大值</td></tr><tr><td>首屏补全类交互</td><td>宽松</td><td>硬 SLO</td><td>不适用，chunk 切分会直接击穿 TTFT</td></tr><tr><td>GPU 接近饱和的高负载段</td><td>p99 严格</td><td>中等</td><td>收益递减，应转向分离式部署或扩容</td></tr></tbody></table>\n<p>一句话指路：分离式预填/解码的跨池 KV 传输与并行策略解耦，由本套书并行与通信部分展开，此处不重复。本方法真正解决的，是“单池、TPOT 优先、TTFT 可让”这一格里的调度粒度问题；把它当成通用加速手段部署到所有场景，事故只会从 TPOT 尖峰迁移到 TTFT 超时。</p>\n<h3 id=\"alg-chunked-prefill-piggyback-sec-7\">七 · 请求入队与 token 级切分：chunk 的诞生点</h3>\n<p>分块预填的第一步不在 GPU 上，而在调度器的等待队列里。新请求到达时携带完整 prompt token 序列，调度器先做一次长度分类：短于一个 chunk 的请求直接整块进入预填；长于一个 chunk 的请求被按固定 token 数切成若干段，每段携带原请求的序列偏移量（offset）与是否为末块的标记。切分粒度是这套机制唯一的硬旋钮，它同时决定三件事：单步前向里 prefill 部分的算力占比、解码 batch 被挤占的时间上界、以及 KV 写入的页对齐质量。</p>\n<p>切分的输入是 prompt 长度 $L$ 与当前 SLO 反推出的 chunk 上限 $C_{\\max}$，输出是一个 chunk 描述符队列，每个描述符含 token 区间、目标 KV 页起始索引、以及该 chunk 走 MoE 时的路由元数据占位。代价发生在调度器侧而非计算侧：每切一刀就多一次调度决策，超长上下文下 chunk 数随 $L/C$ 线性增长，调度开销与描述符内存随之上升。工程上把 $C$ 取成 KV 页大小（例如按页 token 数）的整数倍，使 chunk 边界天然落在页边界上，避免跨页写入产生的页内碎片——这是长上下文下 KV 有效容量不被蚕食的前提。</p>\n<p>具体例子：一个 32K token 的长文档问答请求进入队列，若 $C$ 取数百 token 量级，则该请求被切成数十个 chunk，首个 chunk 立即参与拼批，后续 chunk 在等待队列中按 FIFO 排队；此时队列里同时存在多个长请求的残余 chunk 与若干短请求，调度器看到的是一个混合了「未完成预填」与「待预填」的队列，而不是一个整块的长任务。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-8\">八 · 调度器拼批：一个 chunk 加一个解码 batch</h3>\n<p>每个 iteration 开始时，调度器做一次二元选择：从等待队列头部取一个 prefill chunk，与当前解码队列里的全部解码 token 合并成同一批次。合并后的 batch 在逻辑上是「一段连续 prompt token + 若干条各带一个 token 的序列」，在物理上是同一次前向的输入张量。这一步的输出是一个 batch 描述符，含 token 总数、每条序列的 KV 读写位置、以及 attention 的因果掩码布局。</p>\n<p>拼批的代价直接体现在单步时间上。设单 chunk 前向时间为 $T_{\\text{chunk}}$、解码 batch 前向时间为 $T_{\\text{decode}}$，则单步时间近似为</p>\n<div class=\"formula\">$$T_{\\text{iter}} \\approx \\max(T_{\\text{chunk}}, T_{\\text{decode}})$$</div>\n<p>这个近似成立的前提是两者在同一前向内被并行填充，GPU 的 SM 占用由较大的那一项主导。调度器据此反推满足 SLO 的最大 chunk token 数：</p>\n<div class=\"formula\">$$\\text{chunk\\_size}\\le \\frac{\\text{SLO}_{\\text{TPOT}}-T_{\\text{decode}}}{\\text{每 token 时延}}$$</div>\n<p>公式的含义是：留给 prefill 的时间预算等于 TPOT 上界减去解码本身占用的时间，再除以每 token 的边际时延，得到 chunk 能塞进的 token 上限。注意这是上界而非目标值——取小于上界的 chunk 会浪费吞吐，取等于上界则把 p99 顶在 SLO 边缘，工程上通常取上界的某个折扣系数留出抖动余量。代价的另一面是 TTFT：chunk 越小，长 prompt 的首 token 要等更多个 iteration 才轮到末块，TTFT 被拉长但变得可预测，这正是「TPOT 严格、TTFT 可放宽」场景的取舍点。</p>\n<p>具体例子：解码队列有 64 条序列、每条每步出一个 token，解码前向耗时为数毫秒量级；若 TPOT 的 p99 上界给定，则 chunk 预算被压在数毫秒内，调度器据此把 chunk 限制在数百 token，而不是把整个 32K prompt 一次性灌进去——后者会让单步前向独占 GPU 数十毫秒，期间 64 条解码序列全部停摆。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-9\">九 · 合并 batch 走 MoE 路由与分组 GEMM</h3>\n<p>拼好的 batch 进入模型前向，最先撞上的是 MoE 层的路由。prefill chunk 的 token 与解码 token 在这一层被分别打分、分别选专家，然后合并成一张路由表。分组 GEMM 按专家分组执行，每组的 M 维等于落到该专家的 token 数。问题在于两类 token 的专家分布天然不同：prefill chunk 是连续语义的一段文本，token 之间高度相关，路由结果集中在少数专家；解码 token 来自几十条互不相干的序列，分布更散。合并统计后，分组 GEMM 的形状变得更碎——组数变多、每组 M 变小，tile 利用率下降。</p>\n<p>这一步的输入是合并 batch 的隐状态与路由表，输出是各专家输出的加权和，代价是 GEMM 效率与 All-to-All 通信量。MoE 的 All-to-All 在合并 batch 上执行时，通信量与「激活 token 数 × 专家并行度」成正比；prefill chunk 贡献的 token 数远大于解码 token，因此单步通信量被 chunk 大小主导，这正是 chunk 不能取得太大的另一个原因——它不只拉长计算时间，还拉长通信时间。稳定性技巧是把 prefill chunk 与解码 token 的路由结果合并统计后再分组，避免按来源分别建组导致组数翻倍；合并统计的代价是路由表更大、去重与排序开销上升，但换来的是分组 GEMM 的 M 维更饱满。</p>\n<p>具体例子：某 MoE 层有数十个专家、专家并行度为若干卡，prefill chunk 的数百 token 集中在少数专家、解码的数十 token 散落在其余专家；若不合并统计，分组 GEMM 会出现大量 M 极小的组，tile 填充率低；合并后这些小组被并到相邻组，单步前向的分组 GEMM 时间回落，代价是路由元数据的整理多了一次全局排序。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-10\">十 · KV 写入：chunk 落页与解码追加</h3>\n<p>前向算完，KV 要落地。prefill chunk 的 KV 按 token 顺序写入分页缓存的连续页，解码 token 则在自己序列的 KV 尾部追加一个位置。两者的写入模式不同：chunk 是批量写、页内连续；解码是单点写、跨页跳跃。分页缓存的分配器在这一步要为 chunk 预留足够的空闲页，若空闲页不足，chunk 会被迫等待或缩小，直接表现为 TTFT 抖动。</p>\n<p>代价集中在显存带宽与页碎片两处。chunk 写入的带宽开销与 chunk token 数成正比，且写的是完整的 K 与 V 两份张量；解码追加的带宽开销小但随机性高，页表查询成为隐性成本。当 chunk 边界与页边界不对齐时，一个 chunk 的尾部会占用半页，下一 chunk 从新页开始，页内空洞累积；长上下文下 chunk 数增多，空洞总量上升，KV 缓存的有效容量被挤压，可支持的并发 batch 随之下降。把 $C$ 取成页 token 数的整数倍是消除这类碎片的直接手段，代价是 chunk 粒度被页大小绑死，SLO 反推出的上界若与页大小不整除，只能向下取整，牺牲一点吞吐换容量确定性。</p>\n<p>具体例子：页大小按固定 token 数计，若 chunk 取页大小的整数倍，则每个 chunk 恰好写满整数个页，分配器无需拆分页；若 chunk 取任意值，则每个 chunk 平均浪费半页，数十个 chunk 累积下来相当于损失若干页的容量，在并发 batch 接近显存上限时这就是压垮容量的那部分。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-11\">十一 · 输出解码 token 与请求状态迁移</h3>\n<p>单步前向的尾部，解码 token 从 LM head 采样输出并流式返回给客户端；prefill chunk 不产生可见输出，只推进自己的序列偏移。chunk 完成后，调度器检查该请求是否还有剩余 token：有则留在等待队列等下一个 chunk，无则整条请求转入解码队列，从此每步只贡献一个 token。这一步的输出是「本步解码 token 列表 + 请求状态变更事件」，代价是状态机维护与队列重排。</p>\n<p>状态迁移的工程含义在于队列长度的动态变化。长请求在预填期间占据等待队列但不占解码队列，一旦转入解码队列，解码 batch 突然变长，$T_{\\text{decode}}$ 跳升，若调度器没有预留余量，下一步的 $T_{\\text{iter}}$ 就会顶破 TPOT 上界。因此拼批时要把「即将完成预填的请求数」计入解码 batch 的预期增长，提前压缩 chunk 大小。失败模式在此处最典型：chunk 切得过小时，prefill 吞吐明显下降，长 prompt 请求在等待队列里排队时间不可控，TTFT 被拉长到超出首 token SLO；而 chunk 切得过大时，单步前向被 prefill 主导，解码 TPOT 的 p99 尖峰重现。</p>\n<p>具体例子：一批长短混合的在线对话请求同时到达，短请求几步内完成预填转入解码，长请求仍在切 chunk；若调度器按当前解码队列长度固定 chunk 大小，则短请求集中转入解码的那一步会出现解码 batch 骤增，$T_{\\text{decode}}$ 抬升叠加未缩减的 $T_{\\text{chunk}}$，单步时间越过 SLO；按预期增长动态收缩 chunk 可把这一步的 $T_{\\text{iter}}$ 压回上界内，代价是那几个 chunk 的 prefill 推进变慢。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-12\">十二 · 单步代价的分解与 chunk 取值的工程判断</h3>\n<p>把上述五步的代价按数据流叠起来，单步时间可分解为四块：prefill chunk 的算力时间、解码 batch 的算力时间、MoE 路由与 All-to-All 的通信时间、KV 写入的带宽时间。四者并非简单相加，算力与通信在 MoE 层内可部分重叠，KV 写入可与下一步的调度决策重叠，但 chunk 大小同时进入算力项与通信项，因此存在一个使 $T_{\\text{iter}}$ 最小化的中间取值——它不等于 SLO 允许的最大值，而是「分组 GEMM 形状不碎、All-to-All 不爆、KV 页对齐」三者共同约束下的可行区间。</p>\n<p>工程判断的顺序应是：先由 TPOT 的 p99 上界与 $T_{\\text{decode}}$ 反推 chunk 上界，再把上界向下取整到 KV 页 token 数的整数倍，最后用 MoE 分组 GEMM 的 tile 利用率做二次校验——若该取值下分组 GEMM 的组均 M 低于 tile 高度，则说明 chunk 太小、形状过碎，应向上调整或改用合并路由统计。这个顺序把 SLO 约束放在最前、把硬件效率校验放在最后，避免为了 GEMM 效率牺牲 TPOT 的硬上界。代价是这套判断依赖对 $T_{\\text{decode}}$ 的在线估计，估计偏差会直接传导到 chunk 取值上，因此调度器需要维护解码 batch 前向时间的滑动统计，而不是用固定常数。</p>\n<p>具体例子：同一 GPU 池内 TP 或 EP 拓扑、prefill chunk 与解码 token 共享同一前向、量化沿用既有权重与激活方案、KV 按页写入——在这套部署下，chunk 取值一旦确定，prefill 与解码就被绑在同一并行策略上，无法像分离式部署那样各自用最优 TP/EP 配置；这正是本方法用「无需跨池 KV 传输与 RDMA 带宽」换来的代价，也是它在单池中低负载场景下仍具吸引力的原因。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-13\">十三 · 边界条件：chunk 何时失效，以及每一步的系统代价</h3>\n<p>把步骤摊开看，代价集中在三个交接点上。第一步切分：输入是等待队列中的请求 token 序列，输出是若干固定大小 chunk 及其 KV 页预留，代价是调度器每步要重算 chunk 与解码 batch 的拼批形状——这一步本身不耗 GPU，但 chunk 数与页数成正比，超长上下文时排队结构膨胀，调度开销从微秒级爬到可感知量级。第二步拼批前向：输入是一个 chunk 加当前解码 token，输出是 logits 与新增 KV，代价是单步时间被抬到 $T_{\\text{iter}} \\approx \\max(T_{\\text{chunk}}, T_{\\text{decode}})$，即解码 batch 再小也躲不开一个 chunk 的前向。第三步 KV 落页：chunk 的 KV 按块写入分页缓存、解码 token 追加，代价是页内碎片——chunk 边界不与页边界对齐时，尾页只填一部分，长上下文下有效 KV 容量被吃掉，直接压缩可并发 batch 数。</p>\n<p>失效条件一：chunk 切得过小。此时 prefill 吞吐随 chunk 减小而下降，TTFT 被拉长到超出首 token SLO，长 prompt 请求在队列里等待的时间不再由 token 数决定而是由 chunk 数乘以步数决定，排队时延不可控。失效条件二：MoE 层形状碎裂。prefill chunk 的 token 与解码 token 的专家分布本就不同，合并后路由结果分散，分组 GEMM 的每组 token 数变少，tile 利用率下降，单步前向反而比纯解码更慢——这是“拼批”在 MoE 上最反直觉的代价。失效条件三：并行策略被锁死。同一前向里 prefill 与解码共享 TP/EP 配置，无法像分离式部署那样各自取最优切分，规模上限受 chunk 粒度与分组 GEMM 效率双重制约。</p>\n<div class=\"formula\">$$\\text{chunk\\_size}\\le \\frac{\\text{SLO}_{\\text{TPOT}}-T_{\\text{decode}}}{\\text{每 token 时延}},\\qquad \\text{页碎片}\\propto \\frac{\\text{chunk\\_size}\\bmod \\text{page\\_size}}{\\text{page\\_size}}$$</div>\n<p>工程判断落在两个取值上：chunk 大小取 SLO 允许的最大值以兼顾吞吐，同时把 chunk 边界对齐到 KV 页边界以压碎片；对 MoE 层把 prefill chunk 与解码 token 的路由结果合并统计后再分组，避免每组过碎。适用边界因此很清晰——中低负载、单池部署、TPOT 的 p99 严格而 TTFT 可放宽的在线对话场景；一旦负载升高到解码队列本身已撑满单步时间，chunk 的边际收益就被 $T_{\\text{decode}}$ 淹没，此时该考虑的是分离式池化而非继续调 chunk。</p>\n<h3 id=\"alg-chunked-prefill-piggyback-sec-14\">十四 · 单步时间上界的逐项拆解</h3>\n<p>把 piggyback 的时序写成一条可核算的不等式，是这一机制能被调度器真正使用的先决条件。核心式子是 <span class=\"formula\">$$T_{\\text{iter}} \\approx \\max(T_{\\text{chunk}}, T_{\\text{decode}})$$</span>，它成立的前提是 prefill chunk 与解码 batch 在同一次前向里被拼成同一批次、共享同一组权重读取与同一轮 MoE All-to-All。逐项看：$T_{\\text{chunk}}$ 是单个 chunk 的 token 数除以该批次下的有效 token 吞吐，它随 chunk 线性增长，但斜率不是常数——chunk 越大，GEMM 的 tile 利用率越高，单位 token 时间反而下降；$T_{\\text{decode}}$ 由解码队列长度决定，在 MoE 上它被 All-to-All 主导，因为每层都要把 token 按专家分发再收回，通信量与 token 数成正比而与专家数无关。取 max 而不是求和，是因为两者在同一批次内并行推进，硬件资源（SM、HBM 带宽、NVLink）被同一批 tile 填满，谁更长谁决定这一步的墙钟时间。这一步推导的关键在于：合并批次的总工作量近似为两者之和，但关键路径不是求和，而是资源竞争下的较长者——当 $T_{\\text{chunk}} \\gg T_{\\text{decode}}$ 时，解码 token 实际上是“捎带”在 prefill 的算力空隙里，几乎不额外付费；反之当解码队列很长时，chunk 被挤压到剩余算力里，prefill 进度变慢。工程上这意味着调度器必须同时观测两个量，而不是只盯 chunk 大小。</p>\n<p>由此得到反推 chunk 上界的第二式：<span class=\"formula\">$$\\text{chunk\\_size}\\le \\frac{\\text{SLO}_{\\text{TPOT}}-T_{\\text{decode}}}{\\text{每 token 时延}}$$</span>。分子是留给 prefill 的时间预算：TPOT 的 p99 上界减去解码本身要花的时间，剩下的才是 chunk 可以占用的额度；分母是该模型在该并行配置下每 token 的边际前向时延。这个式子的实用价值在于它把 SLO 直接翻译成调度参数，而不是靠压测试出来。注意两个隐含假设：其一，$T_{\\text{decode}}$ 取的是 p99 而非均值，因为抖动来自长尾而非中位；其二，“每 token 时延”应取 chunk 规模下的实测斜率，若用单 token 解码的时延去代入会严重低估 chunk 容量。举例：若 TPOT p99 预算与解码时延之差只剩数毫秒量级，而每 token 边际时延在亚毫秒量级，则 chunk 只能取很小的 token 数——这正是失败模式里“chunk 过小、prefill 吞吐下降、TTFT 被拉长”的数学来源，不是调参失误，而是预算本身不够。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-15\">十五 · 为什么 max 会退化成求和：MoE 通信项</h3>\n<p>上面的 max 形式在稠密模型上基本成立，在 MoE 上会被 All-to-All 破坏。原因是 All-to-All 不是算力受限而是带宽与同步受限：prefill chunk 的 token 与解码 token 的专家分布不同，合并后一次分发要覆盖两组不相交的专家集合，通信轮次无法被算力掩盖，于是 $T_{\\text{iter}}$ 从 max 滑向 $T_{\\text{chunk}}+T_{\\text{decode}}$ 的加法形态。更精确的写法是把单步拆成三段：<span class=\"formula\">$$T_{\\text{iter}} \\approx T_{\\text{attn}} + \\max(T_{\\text{gemm}}, T_{\\text{a2a}}) + T_{\\text{reduce}}$$</span>，其中 $T_{\\text{a2a}}$ 是合并批次下每层 All-to-All 的墙钟时间，$T_{\\text{reduce}}$ 是收回后的合并与归一化。当 $T_{\\text{a2a}}$ 超过分组 GEMM 的时间，通信就成为关键路径，此时增大 chunk 不再摊薄成本，反而拉长通信。推导的关键一步是认识到 All-to-All 的时延对 token 数近似线性但对专家覆盖数呈阶梯状：合并批次让专家覆盖从“prefill 的热门专家 + 解码的热门专家”变成并集，阶梯跳变一次就多一轮同步。系统代价直接体现在 TPOT 的 p99 尖峰上——这正是材料里“MoE 的 All-to-All 放大阻塞、token 间隔出现尖峰”的机理。工程判断：在 EP 拓扑下应把 chunk 大小与每卡专家数的整除关系纳入约束，使合并批次的专家覆盖尽量落在同一阶梯内，避免每步都触发额外同步轮次。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-16\">十六 · 调度器伪代码：从队列到拼批</h3>\n<p>把机制落到可实现，关键是三件事：切分、拼批、状态迁移。下面给出调度循环的伪代码思路（非可执行代码，只表达控制流与不变量）。</p>\n<ul>\n<li>不变量一：每个 iteration 至多推进一个 prefill chunk，且该 chunk 的 token 数不超过由 SLO 反推的上界；</li>\n<li>不变量二：解码队列中的每个请求每步必须被服务一次，除非其 KV 页不足；</li>\n<li>不变量三：chunk 边界与 KV 分页边界对齐，chunk 尾部不足一页时补齐或延后。</li>\n</ul>\n<p>控制流：等待队列按到达序取出队首请求，读其 prompt 长度 $L$，按 $\\lceil L / \\text{chunk\\_size}\\rceil$ 切分为若干 chunk 并登记剩余 chunk 数；主循环每步先取解码队列构造 decode batch，再判断本步是否有配额取一个 prefill chunk——配额由上一式的预算与当前解码队列长度共同决定，解码队列越长配额越小；将 chunk 的 token 与 decode batch 的 token 拼接为统一 batch，标记每个 token 的来源（prefill 或 decode）以便后续写 KV 时区分；统一 batch 走注意力、MoE 路由、分组 GEMM、All-to-All；前向结束后，prefill 来源的 token 把 KV 写入分页缓存并推进该请求的 chunk 游标，decode 来源的 token 追加 KV 并采样输出；若某请求 chunk 游标到达 $L$，将其从等待队列迁入解码队列，其首 token 即为 TTFT 的落点。这里有一个容易忽略的实现细节：拼批时 prefill token 与 decode token 在序列维度上的位置编码必须各自独立计算，不能因为拼在同一 batch 就共用位置偏移，否则 KV 写入会错位。系统代价上，这套循环每步多出的调度开销是常数级的（队列操作与游标维护），真正的成本在分组 GEMM 的形状碎片化——见下一节。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-17\">十七 · 分组 GEMM 形状碎片的代价与合并路由</h3>\n<p>合并批次后，MoE 层的分组 GEMM 要为“prefill chunk 的专家分组”和“decode token 的专家分组”分别准备 tile。若两组专家集合几乎不相交，则每组 token 数都很少，tile 利用率下降，单步前向反而变慢——这是失败模式里“形状更碎、tile 利用率下降反而拖慢单步”的量化来源。代价可以用一个简单的效率因子表达：<span class=\"formula\">$$\\eta = \\frac{\\sum_g n_g}{\\sum_g \\lceil n_g / T \\rceil \\cdot T}$$</span>，其中 $n_g$ 是第 $g$ 个专家分组的 token 数，$T$ 是 GEMM tile 的 token 维度。$\\eta$ 越接近 1 越好；当 $n_g$ 远小于 $T$ 时 $\\eta$ 急剧下降，硬件算力被 padding 浪费。稳定性技巧是“合并路由统计”：在路由阶段就把 prefill 与 decode 的 token 按专家汇总成一张全局计数表，再据此划分分组，而不是让两路各自分组后再拼接。这样做的代价是路由阶段多一次跨 token 的归约（在 EP 下是一次小规模 All-to-All 或 All-Gather），但换来的是分组数减少、$\\eta$ 提升。举例：若某层有若干专家，prefill chunk 命中其中一部分、解码 token 命中另一部分，各自分组时每组 token 数都低于 tile 阈值；合并统计后若两组有交集，交集专家的 token 数翻倍跨过阈值，$\\eta$ 明显改善。工程判断：当解码队列很短（低负载）时，合并路由的归约开销可能超过收益，此时应退化为不合并、按来源分别分组；这个开关应随解码队列长度动态切换。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-18\">十八 · KV 页对齐与碎片对并发容量的挤压</h3>\n<p>chunk 边界与分页 KV 边界不对齐会产生页内碎片，这在长上下文下直接吃掉可支持的并发 batch。设页大小为 $P$ 个 token，chunk 大小为 $C$，若 $C$ 不是 $P$ 的整数倍，每个 chunk 的尾部都会浪费 $P - (C \\bmod P)$ 个 token 的页容量（当 $C \\bmod P \\neq 0$ 时）。浪费比例可写成 <span class=\"formula\">$$f = \\frac{P - (C \\bmod P)}{C}$$</span>，当 $C$ 略大于 $P$ 的整数倍时 $f$ 最大，接近一整页的浪费摊在一个 chunk 上。系统代价是显存：KV 缓存的有效容量按 $1/(1+f)$ 缩水，可并发请求数同比下降；在长上下文场景下 chunk 数增多，碎片按 chunk 数累加，挤压效应被放大——这正是适用边界里“超长上下文时 chunk 数增多、KV 页碎片上升”的机制解释。工程做法是把 chunk 大小约束为页大小的整数倍，或让 chunk 尾部不足一页时与下一个 chunk 合并（跨请求不可合并，只能在同一请求内延后切分）。代价是 chunk 大小失去一部分自由度，SLO 反推出的上界需要向下取整到页的整数倍，这会略微牺牲 prefill 吞吐换取显存确定性。判断准则：当并发请求数受显存而非算力约束时，页对齐优先；当算力是瓶颈且上下文较短时，可以放宽对齐以换取更大的 chunk。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-19\">十九 · 与分离式部署的公式对照：省掉的传输项</h3>\n<p>把 piggyback 的单步式子与分离式预填/解码部署对照，差别集中在一项上。分离式方案的单步时间可写成 <span class=\"formula\">$$T_{\\text{iter}}^{\\text{disagg}} \\approx T_{\\text{decode}} + T_{\\text{kv\\_xfer}}$$</span>，其中 $T_{\\text{kv\\_xfer}}$ 是把 prefill 产出的 KV 经 RDMA 传到解码池的时间，它与 KV 字节数成正比、与链路带宽成反比，且不受算力掩盖。piggyback 的式子里没有这一项，因为 KV 就地写入同一 GPU 池的分页缓存，代价换成了共享并行策略的约束：两阶段必须用同一套 TP/EP 配置，prefill 偏好大 TP 摊薄权重读取、解码偏好小 TP 降低通信，二者无法各自最优。推导的关键一步是把“省掉的传输”与“让渡的配置自由度”放在同一量纲上比较：前者是每请求一次的固定开销（KV 字节数决定），后者是每 token 的持续效率损失（并行策略错配决定）。因此在低负载、请求稀疏时，分离式的传输项占比高而配置损失不明显，piggyback 占优；在高负载、解码队列长时，配置损失被摊薄到大量 token 上，分离式的传输项反而被流水掩盖。这个对照解释了为什么本方法适合中低负载单池部署，而规模上限受 chunk 切分粒度与 MoE 分组 GEMM 效率制约——两条约束分别来自页对齐的显存代价与合并路由的 $\\eta$ 损失，都是可以在调度器里量化并随负载切换的工程旋钮。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-20\">二十 · 边界、失效条件与系统代价</h3>\n<p>把 chunk 切分当作“免费”的抖动抑制器是这套方案最典型的误读。TPOT 上界由 <span class=\"formula\">$$T_{\\text{iter}} \\approx \\max(T_{\\text{chunk}}, T_{\\text{decode}})$$</span> 给出，但该式只在 chunk 与解码 batch 真正拼成同一前向、且调度器每步严格只取一个 chunk 时成立；一旦 chunk 数超过解码队列长度，单步前向的瓶颈从解码 batch 翻转为 chunk 本身，抖动抑制的收益被 prefill 时间直接吃掉。反推 chunk 大小的约束 <span class=\"formula\">$$\\text{chunk\\_size}\\le \\frac{\\text{SLO}_{\\text{TPOT}}-T_{\\text{decode}}}{\\text{每 token 时延}}$$</span> 中，分母是合并 batch 下每 token 的实测时延，它随 MoE 专家路由的碎片化而上升，因此按静态标定值算出的 chunk 上界在真实负载下会偏大，需要按路由统计动态收紧。</p>\n<p>失效路径有三条，且互相耦合。其一，chunk 切得过小：prefill 吞吐随 chunk 数线性摊薄，TTFT 被拉长到超出首 token SLO，长 prompt 请求在等待队列中的排队时间不可控——这是本方案与分离式部署最本质的取舍，后者可以用独立池子把 TTFT 压住，代价是跨池 KV 传输与 RDMA 带宽。其二，MoE 层中 prefill chunk 与解码 token 的专家分布差异大，合并批次后分组 GEMM 形状更碎，tile 利用率下降，单步前向反而变慢；缓解手段是把两路路由结果合并统计后再分组，但这要求调度器在合并前拿到路由元数据，等于把一部分路由开销前移到了调度路径上。其三，chunk 边界与 KV 分页边界不对齐时产生页内碎片，长上下文下 KV 有效容量下降，直接挤压可支持的并发 batch，形成“抖动抑制→并发下降→解码队列变短→chunk 更难与解码拼批”的负反馈。</p>\n<p>系统代价要按资源维度拆开看：延迟侧，TPOT 的 p99 被 chunk 大小硬性约束，可计算、可承诺，但 TTFT 的均值与方差同时变差；吞吐侧，单池共享并行策略意味着 prefill 与解码无法各自用最优 TP/EP 配置，MoE 的 All-to-All 在合并 batch 下仍按最大并行度走，低负载时通信占比偏高；显存侧，分页缓存按块写入要求 chunk 边界与页边界对齐，否则碎片吃掉有效容量。适用边界因此很清晰：中低负载、单池部署、TPOT SLO 严格而 TTFT 可放宽的在线对话形态；规模上限受 chunk 切分粒度与 MoE 分组 GEMM 效率双重制约，超长上下文时 chunk 数增多、调度开销与页碎片同步上升，此时应转向分离式预填/解码，用跨池 KV 传输换回两阶段各自的并行自由度。</p>\n<h3 id=\"alg-chunked-prefill-piggyback-sec-21\">二十一 · 请求形态与长度分布：长短混合是配方的前提</h3>\n<p>分块预填与解码捎带不是万能调度器，它对请求形态有明确偏好。配方里写得很直白：请求形态为长短混合的在线对话。这句话的技术含义是，队列中同时存在长 prompt（数千 token 的系统提示、检索增强拼接、多轮历史）与短 prompt（单轮追问、工具返回后的续问），并且长请求占比不高、到达不呈突发尖峰。长短混合之所以是前提，是因为该方法的价值来自“把长 prefill 切片塞进解码 batch 的空隙”，如果队列里几乎全是长 prompt，每个 iteration 都在处理 chunk，解码 batch 反而成了捎带方，TPOT 上界退化为 $T_{\\text{chunk}}$ 本身，chunk 切分的收益消失。</p>\n<p>长度分布决定 chunk 数与调度开销。设队列中长请求平均 prompt 长度为 $L$、chunk 大小为 $C$，则该请求占用 $\\lceil L/C \\rceil$ 个 iteration 的 prefill 槽位。超长上下文时 chunk 数增多，调度开销与 KV 页碎片上升——这是材料给出的规模上限来源之一。工程上要看的不是平均长度，而是长度分布的尾部：少量超长请求会把等待队列的 prefill 槽位长期占住，短请求的 TTFT 被这些“慢船”拖住。因此配方隐含一个判断：长度分布的重尾不能太厚，否则需要在准入层做长度分层或对超长请求单独限流。</p>\n<p>具体例子：一个对话服务，系统提示固定 2k token，用户每轮追加数百 token，历史累积到 8k 时触发截断。这类负载的长请求集中在会话前几轮，短请求集中在后续追问，长短混合且长请求可预测——正是配方描述的形态。反过来，一个批量文档摘要服务，每个请求都是 32k 输入、几百 token 输出，队列里没有解码 batch 可捎带，该方法退化为纯分块预填，piggyback 的收益归零。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-22\">二十二 · 并发与批大小：解码队列长度是配方的自变量</h3>\n<p>配方写明批大小由解码队列长度决定。这不是一句描述，而是一个约束：解码 batch 的规模直接进入单步前向时间 $T_{\\text{decode}}$，而 TPOT 上界由 $\\text{TPOT}_{\\text{p99}}\\approx \\max_{\\text{iter}}\\left(T_{\\text{decode}}+T_{\\text{chunk}}\\right)$ 给出。解码队列越长，$T_{\\text{decode}}$ 越大，留给 chunk 的预算 $\\text{SLO}_{\\text{TPOT}}-T_{\\text{decode}}$ 越窄，可用的 chunk 大小被压缩。于是并发与 chunk 大小构成一对反向变量：高并发下 chunk 必须切小以守住 TPOT，而 chunk 切小又压低 prefill 吞吐、拉长 TTFT。这正是该方法适合中低负载的算术根源——并发越高，两个目标越难同时满足。</p>\n<p>把约束写成可执行的判据：调度器每步先测（或估算）当前解码 batch 的前向时间 $T_{\\text{decode}}$，再按</p>\n<div class=\"formula\">$$\\text{chunk\\_size}\\le \\frac{\\text{SLO}_{\\text{TPOT}}-T_{\\text{decode}}}{\\text{每 token 时延}}$$</div>\n<p>反推本步允许的最大 chunk token 数。注意这个不等式是逐步求解的，不是全局常量：解码队列在连续批处理中不断进出，$T_{\\text{decode}}$ 每步都在变，chunk 大小应随之伸缩。工程实现上常见的错误是把 chunk 大小配成静态值，在低并发时浪费了预算（本可以切大 chunk 提吞吐），在高并发时又突破了 TPOT 上界。</p>\n<p>代价落在两个方向。并发偏高时，chunk 被压到很小，prefill 的有效吞吐下降，等待队列排空变慢，TTFT 尾部拉长；并发偏低时，解码 batch 太小，$T_{\\text{decode}}$ 远小于 $T_{\\text{chunk}}$，单步前向由 chunk 主导，GPU 利用率尚可但解码 token 的产出被 chunk 节奏绑架。配方选择中低负载，正是因为在这个区间里 $T_{\\text{decode}}$ 与 $T_{\\text{chunk}}$ 量级相当，两者拼批后单步前向的填充率最高。具体例子：解码队列 8 条、每条每步出 1 token，$T_{\\text{decode}}$ 处于低位，此时可放入接近 SLO 预算上限的 chunk；若解码队列涨到数十条，同一 SLO 下 chunk 预算被显著压缩，调度器必须主动降 chunk 大小，否则 p99 TPOT 越界。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-23\">二十三 · SLO 结构：TPOT 严格、TTFT 可放宽</h3>\n<p>配方的 SLO 取向是单边的：以 TPOT 的 p99 上界为主约束，长 prompt 请求的 TTFT 被拉长但可预测。这句话包含一个交换——用 TTFT 的确定性换 TPOT 的稳定性。可预测是关键限定词：TTFT 变长本身不致命，不可控才致命。分块预填把长 prefill 拆成固定大小的 chunk 后，一个长度为 $L$ 的请求的首 token 等待近似为 $\\lceil L/C \\rceil$ 个 iteration 的时间，只要 $C$ 与调度策略稳定，TTFT 就是可计算的量，可以写进容量规划、可以对外承诺上界。</p>\n<p>反过来说，如果业务 SLO 把 TTFT 卡得很死（例如首 token 必须在百毫秒级返回），该方法就不合适：chunk 切分天然把长 prompt 的首 token 推后，chunk 越小推得越后。配方把“TTFT 可放宽”列为适用边界，等于承认这是一笔明码标价的交易。工程判断上要问的是：业务能否接受长请求的首 token 等待随 prompt 长度线性增长？在线对话通常可以（用户在等待时看到流式输出的首段之前有感知容忍），而交互式补全、语音助手这类场景往往不行。</p>\n<p>稳定性技巧里有一条直接对应 SLO：chunk 大小取 SLO 允许的最大值以兼顾吞吐。这是把不等式从“约束”变成“目标”的用法——在满足 TPOT p99 的前提下尽量切大，让 prefill 吞吐与 TTFT 同时受益。具体例子：SLO 规定 TPOT p99 不超过某阈值，调度器实测 $T_{\\text{decode}}$ 后算出本步 chunk 预算，取预算上限作为 chunk 大小；若某步解码队列骤增导致预算收缩，chunk 自动变小，TPOT 上界仍被守住，代价是这一步的 prefill 推进变慢。整个系统的行为因此是“TPOT 硬约束、TTFT 软约束”，与分离式部署把两阶段各自优化到极致的思路形成对照。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-24\">二十四 · 负载不对时的三种失败模式</h3>\n<p>失败模式一：chunk 切得过小。材料写明，chunk 过小导致 prefill 吞吐下降、TTFT 显著变长，长 prompt 请求排队时间不可控。机制上，每个 iteration 的前向都有固定开销（kernel 启动、路由、通信同步），chunk 越小，固定开销占比越高，prefill 的有效 token 吞吐越低；同时 chunk 数变多，$\\lceil L/C \\rceil$ 增大，首 token 等待被拉长到可能超出首 token SLO。这是配方在“TPOT 严格”一侧用力过猛时的典型翻车：为了守住 p99 TPOT 把 chunk 压到极小，结果 TTFT 违约。</p>\n<p>失败模式二：MoE 分组 GEMM 形状过碎。合并批次里 prefill chunk 与解码 token 的专家分布不同，前者 token 多、分布宽，后者 token 少、分布集中在少数专家。合并统计路由结果后，分组 GEMM 的每组形状更碎，tile 利用率下降，反而拖慢单步前向。这条失败模式的特殊性在于它不由 chunk 大小单独决定，而由“两阶段负载的专家分布差异”决定：当模型专家数多、路由尖锐时，解码 token 落到的专家与 chunk token 落到的专家交集小，合并批次的分组数上升。稳定性技巧给出的对策是将两者的路由结果合并统计，避免形状过碎——本质是用一次统一的分组来摊薄碎片，而不是分别做两次 GEMM。</p>\n<p>失败模式三：KV 页碎片挤压并发。chunk 边界与 KV 分页边界不对齐时产生页内碎片，长上下文下 KV 缓存有效容量下降，挤压可支持的并发 batch。机制上，分页缓存按块分配，chunk 写入若跨页边界，最后一个页块可能只被部分填充；chunk 越小、边界越多，碎片越多。部署配方因此要求 chunk 边界与页边界对齐以减少碎片。三种失败模式共同指向一个判断：负载配方不是调参清单，而是“请求形态—并发—SLO”三者的匹配问题，任何一维偏离，代价都会以 TTFT、单步前向时间或有效 KV 容量的形式显形。</p>\n<table class=\"mini\"><thead><tr><th>偏离维度</th><th>触发条件</th><th>显形代价</th><th>对策</th></tr></thead><tbody><tr><td>chunk 过小</td><td>TPOT 预算被解码 batch 挤窄</td><td>prefill 吞吐下降、TTFT 超首 token SLO</td><td>取 SLO 允许的最大 chunk</td></tr><tr><td>专家分布差异大</td><td>专家数多、路由尖锐</td><td>分组 GEMM tile 利用率下降、单步变慢</td><td>合并统计两阶段路由结果</td></tr><tr><td>页边界不对齐</td><td>超长上下文、chunk 数多</td><td>KV 有效容量下降、并发被挤压</td><td>chunk 边界对齐页边界</td></tr></tbody></table>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-25\">二十五 · 配方与部署形态的耦合：单池、TP/EP、共享并行策略</h3>\n<p>负载配方不能脱离部署配方单独讨论。该方法运行在单机多卡 TP 或 EP 拓扑上，prefill chunk 与解码 token 共享同一前向。这个“共享”是收益来源也是约束来源：收益是不需要跨池 KV 传输与 RDMA 带宽，低负载下 GPU 利用率高于分离式方案；约束是两阶段共享并行策略，无法各自用最优 TP/EP 配置。分离式部署可以让 prefill 池用大 TP、解码池用小 TP 加高并发，而本方法必须取一个折中的并行度，让 chunk 前向与解码前向都在同一套切分下运行。</p>\n<p>这个耦合直接限制了负载配方的适用范围。当 prefill 与 decode 的最优并行策略分歧很大时（例如超长上下文 prefill 需要大 TP 摊平激活，解码需要小 TP 降通信），共享策略会让至少一方偏离最优，单步前向时间里混入了本可避免的通信或计算开销。配方把适用边界写成“中低负载、单池部署”，正是因为在中低负载下，并行策略的分歧尚不足以吃掉 piggyback 的收益；负载一高，分歧的代价被放大，分离式方案的跨池传输成本反而变得可接受。</p>\n<p>具体例子：单机 8 卡 EP 拓扑，专家并行把 MoE 层切分到各卡，All-to-All 在每步前向中发生。chunk 与解码拼批后，All-to-All 的参与方同时包含两阶段的 token，通信量与合并 batch 的 token 总数成正比；若 chunk 切得大，单步通信量上升，$T_{\\text{chunk}}$ 增大，TPOT 上界被推高。这就是材料所说“MoE 的 All-to-All 放大阻塞”的另一面：它不只放大长 prefill 的阻塞，也放大拼批后单步前向的通信开销。配方在 MoE 场景下的稳定性依赖分组 GEMM 的效率与路由合并统计，本质是在通信与计算两个层面同时压碎片的产生。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-26\">二十六 · 负载判据的工程落地：从队列特征到配方选择</h3>\n<p>把配方变成可执行的判据，需要在准入与调度层采集三类队列特征：长度分布的尾部厚度、解码队列长度的波动幅度、长请求到达的突发性。尾部厚、波动大、突发强的负载，chunk 预算被反复压缩，TTFT 不可控，应转向分离式预填/解码部署；尾部薄、波动平缓、长短混合的负载，配方成立，chunk 大小按 SLO 反推并取上限。这个判据不需要实验数字，只需要对队列做在线统计并对照 SLO 结构：TPOT 严格而 TTFT 可放宽，是配方成立的信号；两者都严格，是配方失效的信号。</p>\n<p>落地时还要处理一个调度细节：等待队列中多个请求的 chunk 如何排序。若严格按到达顺序推进，一个超长请求的多个 chunk 会周期性占据 prefill 槽位，短请求的 TTFT 被反复推后；若按 chunk 轮转（每个请求每轮只推进一个 chunk），长请求的 TTFT 被拉长但短请求的等待被压平。配方没有规定排序策略，但“TTFT 可预测”这一条要求排序策略本身是确定的、可计算的，否则 p99 TTFT 无法写进容量规划。工程判断上，轮转式推进配合按 SLO 反推的 chunk 上限，是让负载配方在长短混合队列中保持稳定的组合。</p>\n<p>最后落在机制上：负载配方的核心不是一组静态参数，而是“解码队列长度 → $T_{\\text{decode}}$ → chunk 预算 → chunk 大小 → TTFT 与 prefill 吞吐”这条每步都在变的链条。调度器若能在每个 iteration 重算这条链条并取 SLO 允许的最大 chunk，配方就在中低负载、长短混合、TPOT 严格而 TTFT 可放宽的区间内成立；一旦队列特征偏离这个区间，失败模式会以 TTFT 违约、分组 GEMM 变碎或 KV 有效容量下降的形式出现，此时应换部署形态而不是继续调 chunk 大小。</p>\n<h3 id=\"alg-chunked-prefill-piggyback-sec-27\">二十七 · 硬件档位：按单池拓扑反推卡型与互联预算</h3>\n<p>本方法的部署前提是 prefill chunk 与解码 token 共享同一次前向，因此硬件档位的第一约束不是峰值算力，而是“同一并行组内能否同时容纳两种负载而不互相拖垮”。工程上按单池规模分三档：单卡档（单 GPU 或单节点内 TP=2/4）、单机多卡档（节点内 TP 或 EP，跨卡走 NVLink 5）、以及 NVL72 机柜档（跨节点仍以 NVLink 域为主）。分档依据是 MoE 层 All-to-All 的通信量与 chunk 前向时间的比值：当单 chunk 前向时间被通信主导时，chunk 大小反推出来的 SLO 上界会迅速收紧，此时应降档而不是加卡。</p>\n<p>具体机制上，调度器需要知道每个并行组当前的 $T_{\\text{decode}}$ 与 $T_{\\text{chunk}}$ 实测值，才能解出允许的最大 chunk token 数。给出一个可复现的判定式：设单步迭代时间上界为 SLO 给出的 TPOT p99 预算，则</p>\n<div class=\"formula\">$$\\text{chunk\\_size}\\le \\frac{\\text{SLO}_{\\text{TPOT}}-T_{\\text{decode}}}{\\text{每 token 时延}}$$</div>\n<p>其中“每 token 时延”取该并行拓扑下 prefill 单 token 的边际前向成本。若算出的 chunk_size 小于分组 GEMM 的最小有效 tile token 数（MoE 分组 GEMM 在 token 数过少时 tile 利用率塌陷），说明该档位的并行拓扑不适合本负载，应减少 TP 度、提高单卡承担的专家数，让 chunk 变“厚”。代价侧：TP 度提高会同步放大 All-to-All 与 All-Reduce 的参与卡数，单步迭代的通信尾延迟上升，直接吃掉 TPOT 预算；而 EP 度提高会让每个 rank 的专家数变少、路由更分散，分组 GEMM 形状更碎。例子：一个 8 卡节点上跑 TP=8 的稠密模型，chunk 前向被 All-Reduce 主导，反推 chunk_size 落到很小值，TTFT 被拉长；改为 TP=4 双副本后，单副本 chunk 变厚，SLO 反推的 chunk_size 回到可用区间。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-28\">二十八 · 并行拓扑：prefill 与解码共享策略的取舍</h3>\n<p>共享并行策略是本方法与分离式部署最本质的差别：分离式可以让 prefill 池用大 TP、解码池用大 EP 或大 DP，而 piggyback 方案必须在同一组卡上同时服务两种形态，因此拓扑选择是一次“两阶段折中”。可复现的思路是先把解码侧的约束钉死：解码 batch 的 TPOT 由单 token 前向的通信尾延迟决定，因此 TP 度不应超过让单 token All-Reduce 落在 TPOT 预算内的上限；再把 prefill 侧的约束作为次级条件，用 EP 度吸收 MoE 专家容量。</p>\n<p>伪代码层面的拓扑搜索可以写成：对候选 (TP, EP, DP) 三元组，先测解码单步 $T_{\\text{decode}}$（batch 取解码队列典型长度），再测单 chunk 前向 $T_{\\text{chunk}}$（chunk 取 SLO 反推值），保留满足 $\\max(T_{\\text{chunk}},T_{\\text{decode}})\\le\\text{SLO}_{\\text{TPOT}}$ 的组合，最后在剩余组合里选 prefill 吞吐最高者。这里的关键判据是 $T_{\\text{iter}}\\approx\\max(T_{\\text{chunk}},T_{\\text{decode}})$——两个阶段谁更长，谁就定义迭代节奏；理想配平是让 $T_{\\text{chunk}}$ 略小于 $T_{\\text{decode}}$，使解码不被 chunk 拖慢，同时 chunk 不至于小到浪费 prefill 算力。</p>\n<p>代价与例子：把 EP 度拉到覆盖全部专家时，MoE 层 All-to-All 的参与 rank 数等于 EP 度，通信步数随专家并行线性增长，单 chunk 前向时间里通信占比上升，反推 chunk_size 收缩，形成“越并行越碎”的负反馈。反过来，TP 度不足会让单卡权重与 KV 压力上升，分页缓存的可用块数下降，挤压并发 batch。工程判断是：在中低负载、单池部署的场景下，优先保证解码侧 TPOT 稳定，宁可让 prefill 侧吞吐打折，也不要为了 prefill 吞吐把拓扑推向通信主导区。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-29\">二十九 · 量化方案：沿用既有权重/激活方案，不为 piggyback 单独改精度</h3>\n<p>量化在本方法里不是变量而是常量：部署配方明确要求沿用权重与激活的既有方案，不为拼批单独切换精度。原因是 prefill chunk 与解码 token 在同一前向里走同一套权重，若为 prefill 用高精度、为解码用低精度，等于在同一 iteration 内做两次不同精度的 GEMM，权重需要重复驻留或反复换入，显存与带宽代价直接翻倍，且数值路径不一致会让输出分布漂移，破坏 SLO 的可计算性。</p>\n<p>具体机制上，量化方案的选择要落在“单步前向时间是否被权重带宽主导”这一判据上：当解码 batch 很小、GEMM 呈瘦长形状时，单 token 前向受权重加载带宽约束，低精度权重的收益最大；而 prefill chunk 是胖矩阵，受算力约束，低精度激活的收益体现在 MMA 吞吐上。两者共享同一精度方案时，配方应优先满足解码侧的带宽瓶颈，因为解码是 TPOT 的直接决定项。给出一个带宽估算思路：单步解码的权重流量约等于“激活的权重字节数 × 每卡权重分片比例”，若该流量除以 HBM 带宽得到的加载时间已接近 $T_{\\text{decode}}$，则精度方案没有继续下探的空间，chunk 反推值也会被这个下限卡住。</p>\n<p>代价与例子：把激活精度压低会缩短单 chunk 前向时间，理论上允许更大的 chunk_size、更好的 prefill 吞吐；但若权重精度同步压低导致路由分数与专家选择的数值分辨率下降，MoE 路由在 chunk 与解码 token 混合批次上的专家分布会更不稳定，分组 GEMM 的有效 token 数波动加大。工程判断是：量化方案随模型与硬件档位一次性定死，部署配方里只保留“精度方案不变”这一条硬约束，把调优空间全部留给 chunk 大小与调度参数。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-30\">三十 · KV 策略：chunk 边界与页边界对齐</h3>\n<p>分页 KV 缓存按块写入，而 chunk 是按 token 数切分的，两者边界天然不对齐就会产生页内碎片。本方法的 KV 策略核心是一条对齐规则：chunk 的 token 数取分页块 token 容量的整数倍，使每个 chunk 恰好写满整数个 KV 页，chunk 结束时不留半页。这样 prefill chunk 的 KV 写入是整页提交，解码 token 的追加 KV 落在后续页上，页表更新次数与碎片同时下降。</p>\n<p>机制上，调度器在切分等待队列中的长 prompt 时，先按页容量向上取整再切 chunk，最后一个 chunk 允许不足一页但单独占页；同时维护每个请求的“已写页数”，使 chunk 完成时请求转入解码队列的判定与页提交同步。代价侧：对齐会轻微放大 chunk_size（最多一个页容量），在 SLO 反推的 chunk_size 已经很小时，这个放大比例不可忽略，可能把 $T_{\\text{chunk}}$ 推过 TPOT 预算；因此对齐规则要与 chunk 上限联合校验，若对齐后的 chunk 超限，则改为“页内允许跨 chunk 续写”，用页表偏移记录续写位置，牺牲一点页表复杂度换 SLO 合规。</p>\n<p>例子：长上下文请求的 prompt 被切成若干 chunk，若 chunk 边界落在页中间，每个 chunk 结束时都要为半页保留容量，长上下文下 KV 缓存有效容量下降，可支持的并发 batch 被挤压；改为页对齐后，同样的显存能多容纳若干并发请求。这里的量化判断是定性的：碎片随 chunk 数线性增长，而 chunk 数随上下文长度增长，所以超长上下文是本策略最先失效的场景。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-31\">三十一 · 调度参数：chunk 取 SLO 允许的最大值，路由结果合并统计</h3>\n<p>调度参数只有两类：chunk 大小与批次构成。chunk 大小的取值原则是“取 SLO 允许的最大值以兼顾吞吐”——因为 chunk 越小，prefill 吞吐越低、TTFT 越长，而 TPOT 的上界已经被 $\\max(T_{\\text{chunk}},T_{\\text{decode}})$ 硬性约束，没必要留额外余量。批次构成上，每个 iteration 取一个 prefill chunk 与当前解码 batch 合并，解码 batch 的长度由解码队列决定，调度器不做人为截断，避免解码侧被饿死。</p>\n<p>稳定性技巧落在 MoE 层：prefill chunk 与解码 token 的专家分布不同，合并批次后若分别路由，分组 GEMM 会得到两组形状都很碎的 token 集合；正确做法是把两者的路由结果合并统计，按合并后的专家计数做一次分组，使每个专家的 token 数尽量凑成有效 tile。伪代码思路是：收集本 iteration 全部 token 的路由分数 → 按专家聚合计数 → 以 tile token 数为粒度做容量对齐 → 一次分组 GEMM。代价是聚合步骤引入少量调度开销，但换来 tile 利用率提升，单步前向时间下降，反过来允许更大的 chunk_size。</p>\n<p>失败模式要写进参数校验里：chunk 切得过小时 prefill 吞吐明显下降，TTFT 被拉长到超出首 token SLO，长 prompt 请求排队时间不可控；MoE 层专家分布差异大时，合并批次的分组 GEMM 形状更碎，tile 利用率下降反而拖慢单步前向。因此调度参数应成对设置：chunk 下限由分组 GEMM 的最小有效 tile token 数决定，上限由 TPOT SLO 反推式决定，两者冲突时优先保 SLO、降并行度。例子：在线对话长短混合负载下，按 SLO 反推的 chunk 落在下限附近，此时应减少 TP 度让 chunk 变厚，而不是继续压小 chunk。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-32\">三十二 · 可复现的配置思路：从 SLO 反推，按序定参</h3>\n<p>把上述五节收束成一条可复现的定参顺序，避免在维度空间里乱试。第一步定 SLO：以 TPOT p99 上界为主约束，TTFT 作为放宽项记录在案。第二步定硬件档位与并行拓扑：在候选 (TP, EP, DP) 上实测 $T_{\\text{decode}}$ 与单 chunk $T_{\\text{chunk}}$，用 $\\max$ 判据筛掉超预算组合，优先保解码侧。第三步定量化方案：沿用既有权重/激活方案，用权重带宽估算校验解码单步是否已触底。第四步定 KV 策略：chunk token 数取页容量整数倍，与 chunk 上限联合校验。第五步定调度参数：chunk 取 SLO 反推的最大值，MoE 路由合并统计。</p>\n<p>这套顺序的工程含义是：每一个参数都由前一个参数的实测值约束，而不是拍脑袋给默认值。可复现性体现在两点——判据是显式的公式（$\\text{chunk\\_size}\\le(\\text{SLO}_{\\text{TPOT}}-T_{\\text{decode}})/\\text{每 token 时延}$ 与 $\\max(T_{\\text{chunk}},T_{\\text{decode}})$），失败模式是可枚举的（chunk 过小、GEMM 过碎、页碎片）。与分离式部署相比，本配方省掉了跨池 KV 传输与 RDMA 带宽预算这两项，代价是无法让两阶段各自用最优 TP/EP，这一点在拓扑选择时已经用“优先保解码”的判据吸收掉了。</p>\n<p>最后落在具体机制上：配方里唯一需要在线自适应的是 chunk 大小——调度器每若干 iteration 用实测 $T_{\\text{decode}}$ 重算一次 chunk 上限，若解码队列变长导致 $T_{\\text{decode}}$ 上升，chunk 上限自动收缩，TPOT 上界保持成立；若解码队列变短、$T_{\\text{decode}}$ 下降，chunk 上限放宽，prefill 吞吐回升。这条反馈回路把 SLO 从静态配置变成了运行时不变式，也是本方法在单池中低负载场景下优于分离式方案的根本原因。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-33\">三十三 · 配方边界：何时该退回分离式部署</h3>\n<p>这套配方的硬约束不在算力，而在“共享并行策略”这一条。prefill chunk 与解码 token 拼在同一批次里前向，意味着两者必须共用同一套 TP/EP 切分与同一份权重驻留，无法像分离式预填/解码那样给 prefill 池配大 TP、给解码池配大 EP。于是规模上限由两个量夹住：chunk 切分粒度决定的调度开销，以及 MoE 分组 GEMM 的 tile 效率。超长上下文时 chunk 数线性增多，KV 页碎片与调度队列操作同步上涨，单池方案的边际收益迅速衰减。判断阈值可以直接写成可测的形式：</p>\n<div class=\"formula\">$$\\text{TPOT}_{\\text{p99}}\\approx \\max_{\\text{iter}}\\left(T_{\\text{decode}}+T_{\\text{chunk}}\\right),\\quad \\text{chunk\\_size}\\le \\frac{\\text{SLO}_{\\text{TPOT}}-T_{\\text{decode}}}{\\text{每 token 时延}}$$</div>\n<p>配方取 SLO 允许的最大 chunk 以兼顾吞吐，但这条不等式只在解码队列长度稳定时成立。一旦并发 batch 因 KV 页碎片被压缩，$T_{\\text{decode}}$ 随 batch 变小反而下降，调度器会误判还有余量继续放大 chunk，直到某次 MoE All-to-All 与 chunk 前向叠加，单 iter 冲出数十毫秒，p99 直接破线。因此部署时必须把“KV 有效容量”作为一等监控量：chunk 边界与分页边界对齐，页内碎片在长上下文下会吃掉可支持的并发数，这是最隐蔽的失效路径。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>观测信号</th><th>系统代价</th></tr></thead><tbody><tr><td>chunk 切得过小</td><td>TTFT 抬升、prefill 队列积压</td><td>prefill 吞吐下降，首 token SLO 破线</td></tr><tr><td>专家分布差异大</td><td>分组 GEMM tile 利用率下滑</td><td>单步前向反而变慢，TPOT 抖动回升</td></tr><tr><td>chunk 与 KV 页不对齐</td><td>有效 KV 容量下降</td><td>并发 batch 被挤压，吞吐与 SLO 双输</td></tr></tbody></table>\n<p>工程判断落在负载形态上：中低负载、单池、TPOT 的 p99 严格而 TTFT 可放宽，这套配方最划算——省掉跨池 KV 传输与 RDMA 带宽，GPU 利用率高于分离式方案在低负载下的表现。反过来，一旦请求以长 prompt 为主、TTFT 也是硬 SLO，或集群规模已大到需要 prefill 与解码各自最优并行配置，就应放弃捎带、改走分离式，把 chunk 调度换成跨池流水。对 MoE 层可做的一处补救是把 prefill chunk 与解码 token 的路由结果合并统计后再分组，压住形状碎裂，但这只延缓拐点，不改变拐点存在的事实。</p>\n<h3 id=\"alg-chunked-prefill-piggyback-sec-34\">三十四 · 单步时间预算：chunk 大小如何吃掉 TPOT 余量</h3>\n<p>在 piggyback 方案里，调度器每步只做一件事：把一个 prefill chunk 和解码 batch 拼成同一批次前向。于是单次 iteration 的墙钟时间由两者中较慢的一方决定，写成 $$T_{\\text{iter}} \\approx \\max(T_{\\text{chunk}}, T_{\\text{decode}})$$。解码 batch 的 $T_{\\text{decode}}$ 主要由权重带宽决定——每步要把当前层的权重从 HBM 搬到 SM，batch 变大只摊薄这部分成本，边际增长很缓；而 $T_{\\text{chunk}}$ 随 chunk token 数近似线性增长，因为 prefill 是计算密集的，GEMM 的 FLOPs 与 token 数成正比。这意味着在给定 SLO 下，chunk 大小存在一个硬上界：</p>\n<div class=\"formula\">$$\\text{chunk\\_size}\\le \\frac{\\text{SLO}_{\\text{TPOT}}-T_{\\text{decode}}}{\\text{每 token 时延}}$$</div>\n<p>工程含义是：$T_{\\text{decode}}$ 越接近 SLO，留给 chunk 的余量越薄。MoE 模型尤其如此，解码步里 All-to-All 的固定开销把 $T_{\\text{decode}}$ 抬高，分母里“每 token 时延”又因为专家路由的稀疏性而不易压缩，两个方向同时挤压 chunk 预算。一个具体的判断方法是：在目标 batch 规模下先测出解码单步的稳定耗时，把它从 TPOT SLO 里扣掉，剩下的毫秒数除以单 token prefill 时延，得到的整数就是 chunk 上限。若这个数小到几十个 token，说明该配置下 piggyback 的 prefill 吞吐已经被 SLO 锁死，继续调调度策略没有意义，应当转向分离式部署或放宽 TTFT。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-35\">三十五 · 显存与 KV 页碎片：规模上去后第一个崩的地方</h3>\n<p>piggyback 本身不额外占显存——prefill chunk 与解码 token 共享同一份权重、同一套激活缓冲。真正随规模恶化的是 KV 分页缓存。chunk 的 KV 按块写入分页缓存，块边界若与页边界不对齐，每个 chunk 尾部会留下一个未填满的页。设页大小为 $P$ 个 token、chunk 大小为 $C$，则每个 chunk 平均浪费 $P/2$ 个 token 的页容量，浪费比例约为 $P/(2C)$。当 $C$ 被 SLO 压到接近 $P$ 时，浪费比例逼近 50%——这不是小数。长上下文请求的 chunk 数 $N=\\lceil L/C\\rceil$ 随上下文长度线性增长，碎片总量也随之线性增长，KV 缓存的有效容量被持续侵蚀，可支持的并发 batch 数下降，而并发下降又反过来让解码 batch 变小、$T_{\\text{decode}}$ 的相对固定开销占比上升，形成一条负反馈链。</p>\n<p>缓解手段是把 chunk 大小取成页大小的整数倍，让每个 chunk 恰好填满整数个页；对最后一个不满的 chunk 单独处理，允许它小于标准 chunk 但不产生跨页残留。代价是 chunk 大小不再能自由贴合 SLO 反推值，只能在页粒度的离散格点上取值，调度灵活性下降。另一个代价来自 MoE 专家权重的共存——专家权重按 EP 切分后每卡常驻一份，与 KV 缓存争抢同一块 HBM，KV 碎片化让这场争抢更早触顶。规模上去后，显存先崩的往往不是权重，而是被碎片吃掉的 KV 有效容量。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-36\">三十六 · 带宽与通信：All-to-All 把单步时间拉成尖峰</h3>\n<p>合并批次走 MoE 路由时，prefill chunk 的 token 和解码 token 要一起做 All-to-All。这里有两层代价。第一层是通信量的不对称：prefill chunk 的 token 数远大于解码 token 数，All-to-All 的 payload 由 chunk 主导，通信时间随 chunk 大小增长，与 $T_{\\text{chunk}}$ 同向叠加而不是被 max 掩盖——当 chunk 大到通信时间超过计算时间，$T_{\\text{iter}}$ 的实际瓶颈从 GEMM 转移到 NVLink 上的专家分发。第二层是形状碎片：prefill chunk 与解码 token 的专家分布不同，合并统计后每个专家的 token 数分布更散，分组 GEMM 的每个 tile 变小，tile 利用率下降。极端情况下单步前向反而比不合并更慢，这是 piggyback 最反直觉的失败模式。</p>\n<p>工程上的对策是在路由阶段把两批 token 的路由结果合并统计后再分组，让同一专家的 token 尽量聚到同一个 tile 里，而不是分别路由再拼接。代价是路由阶段需要一次额外的聚合，增加了调度侧的 CPU 开销和一步内的同步点；在 EP 拓扑下这次聚合还要跨卡对齐专家计数，引入一次小规模 All-to-All 或 All-Reduce。带宽账要这样算：NVLink 5 的链路带宽充裕，但 All-to-All 的有效吞吐受限于最慢的那条链路和专家计数的负载均衡，chunk 越大、专家分布越偏，这条最慢链路越容易成为单步时间的决定项。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-37\">三十七 · 功耗与热约束：持续高占用的隐性天花板</h3>\n<p>piggyback 让 GPU 在每一个 iteration 里都同时跑 prefill 和 decode，SM 占用率被抬得很高，功耗曲线比“prefill 阶段满载、decode 阶段轻载”的分离式部署更平。平不等于低——它意味着整机长时间贴着功耗上限运行，涡轮风扇转速和进风温度成为约束。在 NVL72 这种机柜级部署里，单柜功耗预算固定，GPU 持续高占用会把可分配的功率密度推到边界，触发降频。降频直接抬高“每 token 时延”这个分母，反过来压缩 chunk 预算，SLO 反推出来的 chunk 上限变小，prefill 吞吐进一步下降。</p>\n<p>这个链条在低负载时不会显现，因为解码 batch 小、$T_{\\text{decode}}$ 低，chunk 有充足余量；一旦并发上来、解码 batch 变大，功耗贴着上限跑，降频开始吃掉余量，系统进入“越忙越慢”的区间。判断方法是监控单步时间的方差而非均值：均值稳定但 p99 抬升，往往就是热降频在个别 iteration 上触发的信号。缓解手段是给 chunk 大小设一个功耗感知的上限，在机柜功率预算紧张时主动缩小 chunk、拉长 TTFT，把功耗峰值削平——这是用首 token 时延换 TPOT 稳定性的显式交易。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-38\">三十八 · 尾延迟：p99 由最慢的那个 iteration 定义</h3>\n<p>piggyback 的 TPOT 抖动上界由 chunk 大小硬性约束，但这是对“典型 iteration”的约束，不是对尾部的约束。尾部延迟来自三类事件的叠加：一是 chunk 恰好落在 MoE 专家分布最偏的那一步，分组 GEMM 形状最碎、tile 利用率最低；二是 All-to-All 在某条链路上遇到拥塞或专家计数失衡；三是 KV 页分配在长上下文请求上触发一次跨页搬移。三者任一发生，该 iteration 的 $T_{\\text{iter}}$ 就会显著超出 $\\max(T_{\\text{chunk}}, T_{\\text{decode}})$ 的估计值，而 p99 恰恰由这些最慢的 iteration 定义：</p>\n<div class=\"formula\">$$\\text{TPOT}_{\\text{p99}}\\approx \\max_{\\text{iter}}\\left(T_{\\text{decode}}+T_{\\text{chunk}}\\right)$$</div>\n<p>注意这个式子里的 max 是对 iteration 取的，不是对 chunk 和 decode 取的——它表达的是“最慢那一步决定 p99”，因此任何单步异常都会被完整计入。工程上要把 p99 压下来，靠的不是缩小平均 chunk，而是消除异常步：让 chunk 边界与页边界对齐消除搬移，让路由合并统计消除形状碎片，让 chunk 大小取 SLO 允许的最大值以减少 chunk 总数、从而减少异常步出现的次数。chunk 越小，步数越多，异常步的绝对数量越多，p99 反而更难压——这与“chunk 小则抖动小”的直觉相反，是规模上去后尾延迟先崩的机制根源。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-39\">三十九 · 规模上限：哪里先触顶的判据</h3>\n<p>把上述几条代价放在一起，可以给出一个粗略的触顶顺序判据。并发低、上下文短时，piggyback 的瓶颈是 chunk 太小导致 prefill 吞吐不足，表现为 TTFT 拉长但 TPOT 稳定；并发中等、上下文变长时，KV 页碎片先触顶，有效缓存容量下降、可支持并发被压缩；并发高、MoE 专家分布偏斜时，All-to-All 的单步时间超过 GEMM，$T_{\\text{iter}}$ 的瓶颈从计算转移到通信；再往上，功耗与热降频开始侵蚀 SLO 余量，系统进入尾部延迟主导区间。这四道坎的先后顺序取决于模型稀疏度、上下文长度分布和机柜功率预算，但共同点是：每一道坎都会通过“抬高 $T_{\\text{decode}}$ 或降低 chunk 预算”这条通路传导到 SLO 反推公式上，让 chunk 上限单调收缩。</p>\n<p>具体的工程判断是：当 SLO 反推出的 chunk 上限低于一个页大小、或低于分组 GEMM 能维持 tile 利用率的最小 token 数时，piggyback 在这个规模上已经不成立，应当切到分离式预填/解码部署，用跨池 KV 传输换回两阶段各自的并行策略自由。反过来，只要 chunk 上限还显著大于页大小和最小 tile 规模，piggyback 的单池共享前向就是更省带宽、更省显存的选择。这条判据不需要实验数字，只需要在目标配置下测出解码单步耗时、单 token prefill 时延和页大小三个量，就能在部署前判断系统会先撞哪道墙。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-40\">四十 · 规模放大后先崩的那一环：从 chunk 约束到 MoE 分组 GEMM 的 tile 效率</h3>\n<p>这套方案把 TPOT 抖动写成可计算的硬上界，代价是把“可预测性”换成了“每一步都要为最慢的那件事付账”。单步前向时间近似为 <span class=\"formula\">$$T_{\\text{iter}} \\approx \\max(T_{\\text{chunk}}, T_{\\text{decode}})$$</span>，而 p99 又受 <span class=\"formula\">$$\\text{TPOT}_{\\text{p99}}\\approx \\max_{\\text{iter}}\\left(T_{\\text{decode}}+T_{\\text{chunk}}\\right),\\quad \\text{chunk\\_size}\\le \\frac{\\text{SLO}_{\\text{TPOT}}-T_{\\text{decode}}}{\\text{每 token 时延}}$$</span> 约束。工程含义很直接：chunk 越大，prefill 摊到每步的固定开销越少、TTFT 越短，但解码请求被拖慢的步长也越大。调度器据此反推 SLO 允许的最大 chunk token 数——这不是调参，而是把 SLO 直接翻译成 batch 形状的约束。规模上去后第一个崩点往往不是算力，而是这个反推出来的 chunk 太小：当解码 batch 本身已经把 $T_{\\text{decode}}$ 顶到接近 SLO 时，公式给出的 chunk 余量趋近于零，prefill 只能以极小切片前进，TTFT 被拉长到超出首 token SLO，长 prompt 请求在等待队列里排队时间不可控。此时系统并未过载，却已失去对 TTFT 的承诺能力。</p>\n<p>第二个崩点在 MoE 层。合并批次里，prefill chunk 的 token 与解码 token 的专家分布天然不同：前者是长上下文里的密集语义，后者是逐 token 生成的局部路径，路由结果合并统计后分组 GEMM 的每组形状更碎，tile 利用率下降。单步前向反而变慢，$T_{\\text{chunk}}$ 与 $T_{\\text{decode}}$ 同时被抬高，公式里的余量进一步收窄，形成正反馈。All-to-All 通信在这里是放大器：分组越碎，需要跨卡交换的 token 越多、每次交换的有效载荷越小，带宽利用率与延迟同时恶化。缓解手段是把两类的路由结果合并统计后再分组，尽量凑出规整的 tile；但这要求路由统计在 chunk 与 decode 之间共享，调度器与 MoE 层不再是解耦的两个模块。代价体现在单步延迟上：合并统计本身要一次同步，在 TP/EP 拓扑下就是一次集合通信，低负载时这笔开销占比可观。</p>\n<p>第三个崩点在显存与 KV 页碎片。chunk 边界若与分页缓存页边界不对齐，每个 chunk 尾部都会留下页内空洞；长上下文下 chunk 数随 prompt 长度线性增长，空洞累积使 KV 缓存有效容量下降，直接挤压可支持的并发 batch。并发下降又反过来削弱解码 batch 的规模，使 $T_{\\text{decode}}$ 变小、公式允许更大的 chunk——看似缓解，实则把压力转移到 TTFT 与页碎片上。可用下表对照不同规模阶段的先崩环节：</p>\n<table class=\"mini\"><thead><tr><th>规模阶段</th><th>先崩环节</th><th>系统代价</th><th>工程对策</th></tr></thead><tbody><tr><td>中低负载、单池</td><td>基本不崩，chunk 取 SLO 允许最大值</td><td>TTFT 可预测地拉长</td><td>按 SLO 反推 chunk，页边界对齐</td></tr><tr><td>解码队列变长</td><td>chunk 余量趋零，TTFT 失控</td><td>首 token 排队，SLO 违约</td><td>限制并发或降级为分离式</td></tr><tr><td>MoE + 多卡 EP</td><td>分组 GEMM tile 变碎、All-to-All 放大</td><td>单步前向变慢，TPOT 尖峰</td><td>合并路由统计，凑整 tile</td></tr><tr><td>超长上下文</td><td>KV 页碎片，有效容量下降</td><td>并发 batch 被挤压</td><td>chunk 与页边界对齐</td></tr></tbody></table>\n<p>与分离式预填/解码相比，本方案省掉了跨池 KV 传输与 RDMA 带宽，代价是两阶段共享同一套并行策略，无法各自用最优 TP/EP 配置——prefill 偏好大 TP 摊薄权重读取，decode 偏好小 TP 降通信，共享拓扑意味着总有一方在非最优区工作。功耗维度上，合并批次让 GPU 在 prefill 与 decode 之间反复切换 SM 占用形态，tcgen05 与 TMEM 的流水更难保持长驻，能效比纯解码阶段低；这在单池中低负载下可接受，在满载时则表现为每 token 能耗上升。判断边界很清楚：TPOT SLO 严格而 TTFT 可放宽、单池部署、MoE 分组 GEMM 能凑出规整 tile 时，这套方案优于分离式；一旦解码队列长到 chunk 余量消失，或超长上下文把页碎片推到容量红线，就该切回分离式或引入跨池 KV 传输，把 prefill 的阻塞从解码路径上彻底摘出去。</p>\n<h3 id=\"alg-chunked-prefill-piggyback-sec-41\">四十一 · 精度漂移：合并批次里的数值一致性</h3>\n<p>piggyback 把 prefill chunk 与解码 token 拼进同一批次，最先出问题的往往不是性能而是数值。解码 token 走的是增量路径——KV 已落盘、激活只有一行；prefill chunk 走的是批量路径——激活是整块矩阵、KV 一次性写入。两条路径若在量化上不一致，同一模型在不同 token 上会给出系统性偏差。具体机制在于：MoE 分组 GEMM 对 prefill chunk 采用按 tile 的激活微缩放（材料未给出具体位宽），而解码 token 因行数太少常退化为按 token 或按通道缩放，两者对同一权重张量的量化误差方向不同，合并后 router logits 的分布被拉偏，专家选择在 chunk 与 decode 之间出现系统性偏移。诊断上不要只看 loss，要在服务侧挂一个逐层激活的统计探针：对每个 iteration 记录合并批次中 prefill 部分与 decode 部分各自的路由熵、top-k 专家重合率、以及分组 GEMM 输出的 per-tile amax。若 decode 部分的 amax 长期低于 prefill 部分一个量级以上，说明两条路径的缩放因子没有对齐，需要把 decode 也强制走与 prefill 相同的 tile 级缩放。代价是解码路径多一次 amax 归约，单步前向增加少量带宽开销，但换来的是可回滚的确定性。一个具体例子：同一 prompt 在纯解码阶段与 piggyback 阶段对同一 token 的 top-1 专家不一致率超过阈值时，直接把该请求标记为“精度可疑”，路由到不带 piggyback 的保守队列，而不是继续在合并批次里跑。</p>\n<div class=\"formula\">$$\\text{drift}=\\frac{1}{L}\\sum_{l}\\left|\\,\\text{amax}^{\\text{prefill}}_{l}-\\text{amax}^{\\text{decode}}_{l}\\,\\right|/\\text{amax}^{\\text{prefill}}_{l}$$</div>\n<p>这个 drift 指标按层求平均，超过经验阈值就触发回滚到统一缩放路径。它不依赖任何实验数字，只依赖运行时探针，因此可以在不重训的前提下定位问题层。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-42\">四十二 · OOM 与 KV 页碎片：chunk 边界不对齐的代价</h3>\n<p>显存侧的失败模式比精度更直接。分页 KV 按块分配，chunk 边界若与页边界不对齐，每个 chunk 的尾部都会在最后一页留下空洞；长上下文下 chunk 数增多，这些页内碎片累积起来，KV 缓存的有效容量被侵蚀，可支持的并发 batch 数随之下降，最终表现为调度器反复拒绝新请求或触发抢占式驱逐。机制上，chunk 大小应取页 token 数的整数倍，并在切分时把最后一个不满页的 chunk 与相邻 chunk 合并，而不是让它单独占一页。诊断要盯三个量：分页缓存的页利用率、每 iteration 的 KV 分配失败次数、以及被驱逐请求的重算比例。页利用率跌破阈值说明碎片化已开始挤压容量；分配失败次数上升说明调度器已在 OOM 边缘；驱逐重算比例上升则说明 piggyback 的收益正在被重算成本吃掉。代价是合并尾部 chunk 会让单 chunk 略大于 SLO 反推的上界，TPOT p99 有轻微上抬，因此合并只允许发生在队列尾部且不超过上界的一个页。一个具体例子：超长上下文请求把 prompt 切成数十个 chunk 时，若每个 chunk 尾部都留半页空洞，KV 有效容量按 chunk 数线性下降，此时应改为按页对齐切分并把余数并入最后一块。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-43\">四十三 · 批抖动与路由不均：MoE 层的形状碎片</h3>\n<p>piggyback 最隐蔽的失败模式是“越合并越慢”。prefill chunk 的 token 分布是长程语义，解码 token 是逐字生成，两者在 MoE 层的专家分布差异大；合并后路由结果被合并统计，分组 GEMM 的每个专家分组都变小且形状更碎，tile 利用率下降，单步前向反而慢于分开跑。诊断不能只看 iteration 总时间，要拆到 MoE 层：记录每层每个专家的 token 数、分组 GEMM 的 tile 占用率、以及 All-to-All 的通信量。若合并批次的 tile 占用率显著低于纯 prefill 批次，说明形状碎片已经吃掉 piggyback 的收益。机制上的对策是对路由结果做合并统计后再分组，把 prefill 与 decode 落在同一专家上的 token 拼成连续分组，而不是各自独立分组；同时给分组 GEMM 设一个最小 tile 阈值，低于阈值的专家分组回退到稠密路径。代价是稠密回退增加算力消耗，但避免了碎 tile 的空转。批抖动的另一个来源是解码队列长度波动：解码 batch 突然变长时，$T_{\\text{decode}}$ 抬升，与 $T_{\\text{chunk}}$ 的相对关系翻转，TPOT p99 出现尖刺。监控应同时记录 $T_{\\text{chunk}}$ 与 $T_{\\text{decode}}$ 的比值，比值剧烈震荡说明 chunk 大小与当前解码负载不匹配，需要按队列长度动态收缩 chunk。</p>\n<div class=\"formula\">$$\\text{TPOT}_{\\text{p99}}\\approx \\max_{\\text{iter}}\\left(T_{\\text{decode}}+T_{\\text{chunk}}\\right),\\quad \\text{chunk\\_size}\\le \\frac{\\text{SLO}_{\\text{TPOT}}-T_{\\text{decode}}}{\\text{每 token 时延}}$$</div>\n<p>这条上界是诊断的基准线：任何一次 iteration 的实测值超过它，就说明该步的合并批次里出现了非预期的阻塞，应回查当步的 MoE 分组形状与 All-to-All 通信。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-44\">四十四 · 尾延迟尖刺：All-to-All 与调度抖动的叠加</h3>\n<p>尾延迟尖刺通常不是单点故障，而是两个抖动源叠加：MoE 的 All-to-All 在合并批次上同步等待最慢的专家分组，而调度器在 chunk 完成瞬间把请求从 prefill 队列搬到解码队列，队列长度突变又改变下一步的批组成。机制上，All-to-All 的完成时间由最大分组决定，形状越碎最大分组越不可预测；调度搬移则让相邻两个 iteration 的批组成完全不同，$T_{\\text{decode}}$ 在两步之间跳变。诊断要把 p99 尖刺对应到具体 iteration，再拆成通信等待时间与计算时间两部分：若尖刺步的通信等待占比高，问题在路由不均；若计算时间跳变而通信平稳，问题在批组成突变。对策是给 chunk 完成后的请求搬移加一个平滑窗口，让新转入解码队列的请求在下一个 chunk 边界才参与合并，避免单步批组成突变；同时对 All-to-All 设超时与降级路径，超时分组回退到本地专家计算。代价是平滑窗口让部分请求的解码晚一个 chunk 开始，TTFT 略增，但换来 p99 尖刺的可预测性。一个具体例子：长 prompt 的最后一个 chunk 完成时，若同时有多个请求转入解码队列，下一步的解码 batch 骤增，$T_{\\text{decode}}$ 抬升叠加 All-to-All 等待，p99 出现尖刺；平滑窗口把这次搬移摊到两个 chunk 边界，尖刺被削平。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-45\">四十五 · 监控面与回滚开关</h3>\n<p>监控要覆盖四个面，每个面对应一类失败模式：数值面（逐层 amax drift、路由重合率）、显存面（页利用率、KV 分配失败、驱逐重算比例）、形状面（MoE 分组 tile 占用率、$T_{\\text{chunk}}/T_{\\text{decode}}$ 比值）、尾延迟面（p99 尖刺步的通信与计算拆分）。四个面共用一个 iteration 级的时间线，任何指标越界都能定位到具体步与具体层。回滚不是全有全无，而是分级开关：一级回滚关闭 piggyback 的合并，prefill 与 decode 分开跑，牺牲吞吐换确定性；二级回滚保留合并但强制统一量化缩放与页对齐切分；三级回滚只关闭动态 chunk 收缩，固定 chunk 大小回到 SLO 反推的静态值。分级的意义在于把回滚代价控制在最小范围——多数精度问题只需二级，多数 OOM 只需页对齐，只有尾延迟尖刺失控才需要一级。工程判断上，piggyback 的稳定性不取决于单点优化，而取决于这四个面是否在同一时间线上可观测；没有 iteration 级时间线的监控，任何回滚都是盲回滚。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-46\">四十六 · 失败模式与诊断：从 chunk 边界到 MoE 路由的四个断点</h3>\n<p>捎带方案把 TPOT 抖动约束在 $T_{\\text{iter}} \\approx \\max(T_{\\text{chunk}}, T_{\\text{decode}})$ 之内，但这条上界只在 chunk 尺寸、KV 页边界、专家路由三者同时受控时成立。工程上最先崩的往往不是公式本身，而是公式之外的三个耦合点。第一个断点是 chunk 过小：调度器为压低 p99 TPOT 把 chunk 切到几十个 token，单步前向里 prefill 的有效算力占比骤降，分组 GEMM 的 tile 填充率随之恶化，prefill 吞吐明显下降，TTFT 被拉长到超出首 token SLO，长 prompt 请求在等待队列里的排队时间变得不可控——此时 TPOT 达标而 TTFT 失守，SLO 从一条约束变成两条互相拉扯的约束。诊断上应同时采集 chunk 队列深度、每步 prefill token 数与 TTFT p99，若三者同向恶化即可判定为切分过细，回滚手段是调大 chunk_size 并接受 TPOT p99 的小幅抬升。</p>\n<p>第二个断点在 MoE 层。prefill chunk 的 token 来自同一段长 prompt，专家分布高度集中；解码 token 来自多个会话，分布弥散。两者拼进同一批次后，路由结果的并集被拉宽，分组 GEMM 形状更碎，单步前向的 tile 利用率下降，反而拖慢 $T_{\\text{chunk}}$ 与 $T_{\\text{decode}}$ 中的较大者。这正是 All-to-All 放大阻塞的微观来源：通信量与专家数成正比，而碎片化的分组让每组的 token 数低于高效阈值。监控应把 prefill 与 decode 的路由直方图分开统计再取并集，观察合并后每组平均 token 数；若该值持续低于分组 GEMM 的高效区间，说明捎带在 MoE 上已不经济，回滚到按层拆分或对 MoE 层单独走分离式路径比继续调 chunk 更有效。</p>\n<p>第三个断点是 KV 页碎片。chunk 边界与分页缓存页边界不对齐时，每个 chunk 的尾部在页内留下空洞，长上下文下 chunk 数增多，空洞累积使 KV 缓存有效容量下降，直接挤压可支持的并发 batch，表现为 OOM 或调度器被迫缩批。可用下面的近似判断碎片代价：</p>\n<div class=\"formula\">$$\\text{有效容量}\\approx \\frac{\\text{页大小}}{\\text{页大小}+\\text{平均页内空洞}}\\times\\text{物理 KV 容量},\\quad \\text{空洞}\\approx \\frac{\\text{页大小}-\\text{chunk\\_size}\\bmod\\text{页大小}}{2}$$</div>\n<p>把 chunk_size 取为页大小的整数倍即可把空洞压到零，代价是 chunk 粒度变粗、TPOT 上界放宽，这又是一次吞吐与抖动的交换。诊断信号是 KV 缓存占用率与并发 batch 数的背离：占用率上升而 batch 数下降，基本可锁定为页碎片而非真实显存不足。</p>\n<p>第四个断点是路由不均与尾延迟尖刺。TP 或 EP 拓扑下，合并批次里各 rank 分到的 prefill token 数取决于路由结果，专家热点会让某个 rank 的 All-to-All 成为单步前向的临界路径，$T_{\\text{iter}}$ 的实际值超过 $\\max(T_{\\text{chunk}}, T_{\\text{decode}})$，p99 出现与 chunk 尺寸无关的尖刺。这类尖刺无法用调 chunk 消除，只能靠逐 rank 的 All-to-All 耗时与专家负载方差定位。监控面板应把每步的 prefill token 数、decode token 数、逐 rank 通信耗时、专家负载方差、KV 页空洞率、TTFT p99 与 TPOT p99 放在同一时间轴上，任何一次尖刺都能回溯到具体断点。回滚顺序建议为：先对齐页边界，再调 chunk_size 至 SLO 允许的最大值，最后才考虑把 MoE 层从捎带批次中摘出——因为前两步是配置变更，第三步是架构变更，代价依次递增。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>主诊断信号</th><th>系统代价</th><th>回滚动作</th></tr></thead><tbody><tr><td>chunk 过小</td><td>TTFT p99 上升、每步 prefill token 数偏低</td><td>prefill 吞吐下降、排队时间不可控</td><td>调大 chunk_size</td></tr><tr><td>MoE 形状碎片化</td><td>合并后每组平均 token 数偏低</td><td>单步前向变慢、tile 利用率下降</td><td>MoE 层摘出捎带批次</td></tr><tr><td>KV 页碎片</td><td>占用率升、并发 batch 降</td><td>有效 KV 容量下降、OOM 风险</td><td>chunk 对齐页边界</td></tr><tr><td>路由不均</td><td>逐 rank All-to-All 耗时方差大</td><td>尾延迟尖刺、p99 失控</td><td>调 EP 布局或限流热点专家</td></tr></tbody></table>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-47\">四十七 · 捎带批次的失效边界：从页碎片到专家形状</h3>\n<p>这套方案最脆弱的假设是“chunk 边界与 KV 分页边界天然对齐”。分页缓存按固定 token 块分配，而 chunk 大小由 SLO 反推得出，两者一般不是整数倍关系。一个 chunk 的尾部落在页中间时，该页剩余槽位在 chunk 完成前无法被其他请求复用，长上下文场景下 chunk 数随 prompt 长度线性增长，页内碎片随之累积，KV 有效容量被侵蚀，可并发的解码 batch 反而缩小——这与“提高利用率”的初衷相悖。工程上的做法是把 chunk_size 向上取整到页 token 数的整数倍，代价是牺牲一部分 SLO 余量；若页尺寸为 P、chunk 为 C，则有效利用率约为 ⌊C/P⌋·P/C，C 越接近 P 的整数倍损失越小。监控上应直接采集“已分配页数 / 已用 token 数”的比值，该比值持续偏离 1 即说明碎片在恶化。</p>\n<p>第二个失效点是 MoE 层的分组 GEMM 形状退化。prefill chunk 的 token 来自同一段长 prompt，路由高度集中到少数专家；解码 token 分布则分散且随请求漂移。两者拼批后，分组 GEMM 的每个专家分组都变小且数量变多，tile 利用率下降，单步前向时间可能不降反升。判别方法是分别记录合并批次与纯解码批次的单步耗时：若 $T_{\\text{iter}}$ 在并入 chunk 后超过 $\\max(T_{\\text{chunk}}, T_{\\text{decode}})$ 的预测值，说明形状碎裂已经吃掉收益。缓解手段是对两路路由结果做合并统计后再切组，或对 chunk 侧做专家亲和的重排，把同一专家的 token 聚到连续位置。</p>\n<div class=\"formula\">$$\\text{TPOT}_{\\text{p99}}\\approx \\max_{\\text{iter}}\\left(T_{\\text{decode}}+T_{\\text{chunk}}\\right),\\quad \\text{chunk\\_size}\\le \\frac{\\text{SLO}_{\\text{TPOT}}-T_{\\text{decode}}}{\\text{每 token 时延}}$$</div>\n<p>第三类是调度侧的批抖动与路由不均。解码队列长度决定批大小，队列短时 chunk 占比升高，TTFT 被拉长；队列长时 chunk 被挤压，prefill 吞吐下降、等待队列堆积，形成正反馈式的尾延迟尖刺。诊断应同时看三个量：等待队列的 chunk 数、解码队列的 token 数、以及每步实际并入的 chunk token 占比。占比长期低于阈值说明 chunk 被饿死，高于阈值说明解码被拖慢。回滚路径要预先设计：把 chunk_size 调回上一档、或将长 prompt 请求临时路由到独立池，都是可逆操作；关键是 chunk_size 必须作为可热更新的调度参数而非编译期常量，否则故障时只能重启实例。OOM 则多由页碎片与并发上限共同触发，回滚时应先降并发上限再动 chunk_size，避免二次抖动。</p>\n<h3 id=\"alg-chunked-prefill-piggyback-sec-48\">四十八 · 同族算法的坐标：三条轴上的取舍</h3>\n<p>分块预填与解码捎带（chunked prefill + piggyback）不是孤立技法，它落在三个连续变量的中间地带：<strong>prefill 与 decode 是否共享同一前向</strong>、<strong>是否跨池传输 KV</strong>、<strong>是否引入额外模型或草稿做投机</strong>。把同族算法排在这三条轴上，选择就变成定位问题而非偏好问题。最左端是朴素连续批处理：prefill 整段插入，长 prompt 独占 GPU 数十毫秒，解码请求被饿死，TPOT p99 直接由最长 prefill 决定。最右端是分离式预填/解码部署：prefill 池与 decode 池各自用最优 TP/EP，代价是跨池 KV 传输占用 RDMA 带宽并引入额外跳数时延。本方法居中：同一 GPU 池内把 prefill 切片，与解码 token 拼成一批，既保留共享前向的利用率，又用 chunk 大小给 TPOT 抖动上了硬上界。</p>\n<p>第三条轴上，MoE 投机解码与容量因子路由属于“改变 token 流”的一族，与本方法正交但会互相干扰：投机解码在 decode 侧一次前向验证多个草稿 token，抬高单步 $T_{\\text{decode}}$；容量因子路由在 MoE 层丢弃溢出 token，改变分组 GEMM 的实际形状。二者都会改变本方法赖以反推 chunk 大小的那个不等式，因此选型时必须把它们当作输入参数而非并列选项。工程判断的第一条：先确定 decode 侧单步时延的构成，再决定 chunk 预算，顺序不能颠倒。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-49\">四十九 · 决策表：按约束条件落位</h3>\n<p>下表把可用事实中的适用边界压成可执行的判据。每一行给出一个主导约束，以及在该约束下本方法与相邻方案的相对优劣。表中不出现实验数字，只标注定性方向与已知的机制性代价。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>主导约束</th><th>首选</th><th>次选</th><th>关键代价</th></tr>\n</thead>\n<tbody>\n<tr><td>TPOT p99 严格、TTFT 可放宽</td><td>分块预填 + 捎带</td><td>分离式部署</td><td>chunk 小则 prefill 吞吐降、TTFT 拉长</td></tr>\n<tr><td>TTFT 严格、TPOT 宽松</td><td>朴素连续批处理或 prefill 优先</td><td>分块预填（大 chunk）</td><td>解码被长 prefill 阻塞数十毫秒</td></tr>\n<tr><td>两阶段需各自最优 TP/EP</td><td>分离式预填/解码</td><td>—</td><td>跨池 KV 传输占 RDMA 带宽</td></tr>\n<tr><td>中低负载、单池、GPU 数有限</td><td>分块预填 + 捎带</td><td>—</td><td>共享并行策略，两阶段无法各自调优</td></tr>\n<tr><td>超长上下文、chunk 数多</td><td>分离式或大 chunk 折中</td><td>分块预填</td><td>调度开销与 KV 页碎片上升</td></tr>\n<tr><td>MoE 专家分布 prefill/decode 差异大</td><td>分离式（避免拼批）</td><td>合并路由统计的分块预填</td><td>分组 GEMM 形状碎、tile 利用率降</td></tr>\n</tbody>\n</table>\n<p>读表方式：先看第一列哪一行成立，再看第三列的代价是否落在可接受区间。若两条约束同时严格（TPOT 与 TTFT 都紧），本方法与分离式都不完美——本方法牺牲 TTFT，分离式牺牲带宽与部署复杂度，此时应回到 SLO 容量规划，用下面的不等式判断哪一侧的松弛更便宜。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-50\">五十 · 用同一个不等式做跨算法比较</h3>\n<p>本方法的核心约束是单步前向时间被 chunk 与 decode 两者中的较大者支配：</p>\n<div class=\"formula\">$$T_{\\text{iter}} \\approx \\max(T_{\\text{chunk}}, T_{\\text{decode}}),\\quad \\text{chunk\\_size}\\le \\frac{\\text{SLO}_{\\text{TPOT}}-T_{\\text{decode}}}{\\text{每 token 时延}}$$</div>\n<p>这个式子的价值在于它可以直接搬去评估相邻方案。对朴素连续批处理，$T_{\\text{chunk}}$ 等于整段 prefill 的前向时间，长 prompt 下可达数十毫秒，$\\max$ 恒取 $T_{\\text{chunk}}$，TPOT p99 失去上界，不等式右端无解——这就是它在本约束下不可选的数学理由，而非经验之谈。对分离式部署，$T_{\\text{iter}}$ 退化为纯 $T_{\\text{decode}}$，不等式自动满足，代价转移到跨池 KV 传输：每 token 的 KV 需经 RDMA 搬运，带宽占用与跳数时延进入 TTFT 与 TPOT 的公共开销，且两池的 batch 无法互相填充，低负载时利用率下降。</p>\n<p>对本方法，chunk 大小是唯一可调的自由度。取 SLO 允许的最大值可兼顾 prefill 吞吐；取小则 TPOT 更稳但 TTFT 拉长。伪代码层面的调度判断只有一句：每步从等待队列取一个 chunk，与解码 batch 合并，若合并后预估 $T_{\\text{iter}}$ 超过 SLO 上界则缩小 chunk。这个判断的输入是 $T_{\\text{decode}}$ 的实测值与每 token 时延的估计，二者都随 MoE 路由分布与量化方案漂移，因此调度器需要周期性重估而非一次性标定。</p>\n<p>系统代价的对照要落到具体资源上。本方法的显存开销来自分页 KV 按块写入，chunk 边界与页边界对齐可减少碎片；不对齐时页内碎片在长上下文下挤压并发 batch 容量。分离式方案的显存分布在两个池，KV 需在池间复制或流式传输，显存总量上升而单池压力下降。朴素方案的显存最省，但 TPOT 抖动使其在严格 SLO 下需要过度预留算力，实际容量反而更低。功耗维度上，本方法因共享前向减少了空转，低负载时优于分离式的双池待机。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-51\">五十一 · 具体例子：一条长 prompt 在三种方案下的走向</h3>\n<p>设一个在线对话服务，解码队列稳定有若干请求在跑，突然进入一条长 prompt。朴素连续批处理下，这条 prompt 的 prefill 一次前向独占 GPU 数十毫秒，期间所有解码请求的 token 间隔出现尖峰，TPOT p99 被这一个请求定义。分离式部署下，长 prompt 被路由到 prefill 池，decode 池不受影响，TPOT 平稳，但该请求的 KV 需跨池传输，TTFT 增加一跳传输时延，且 prefill 池在低负载时利用率偏低。</p>\n<p>本方法下，长 prompt 被切成若干 chunk，每个 iteration 只处理一个 chunk 并与当前解码 batch 拼批。解码 token 每步照常输出，TPOT 抖动被 chunk 大小硬性约束在 $\\max(T_{\\text{chunk}}, T_{\\text{decode}})$ 内；该请求的 TTFT 被拉长为 chunk 数乘以单步时间，但可预测、可写入 SLO。若该模型是 MoE，合并批次后 prefill chunk 与解码 token 的专家分布不同，分组 GEMM 形状更碎，tile 利用率下降可能反而拖慢单步前向——此时应把两者的路由结果合并统计，按合并后的专家负载重排分组，而不是让两套路由各自成组。这个例子说明：本方法的收益在 TPOT 侧确定，风险在 MoE 分组 GEMM 效率侧，选型时必须确认后者不抵消前者。</p>\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-52\">五十二 · 适用条件与规模上限的工程判据</h3>\n<p>本方法的适用条件可归为四条同时成立：单池部署、中低负载、TPOT SLO 严格而 TTFT 可放宽、模型并行策略在两阶段间可共享。四条中任一不成立，就应转向相邻方案。单池不成立（已有两套异构池）选分离式；负载高到解码队列长期饱和时，chunk 与 decode 的拼批收益被 $T_{\\text{decode}}$ 主导，本方法退化为普通连续批处理，此时应改用分离式让两阶段各自扩容；TTFT 严格时 chunk 必须取小，prefill 吞吐下降与排队时间不可控会同时出现，属于已知失败模式。</p>\n<p>规模上限由两个机制性因素决定。其一是 chunk 切分粒度：超长上下文下 chunk 数增多，每步的调度开销与 KV 页碎片累积，有效 KV 容量下降，反过来限制并发 batch。其二是 MoE 分组 GEMM 效率：prefill chunk 与解码 token 的专家分布差异随 batch 组成变化，形状越碎 tile 利用率越低，单步前向被拖慢后 $\\max$ 取值上移，SLO 反推出的 chunk 上限被压缩，形成负反馈。工程上应监控两个量：单步前向时间的分布（判断 $\\max$ 由谁支配）与 KV 页有效利用率（判断碎片是否已成瓶颈）。前者上升说明分组 GEMM 或 chunk 过大，后者下降说明 chunk 边界与页边界失配。</p>\n<p>最后一条判断落在并行策略上：本方法要求 prefill 与 decode 共享同一套 TP/EP 配置，这意味着无法为 prefill 选大 TP、为 decode 选大 EP。当模型规模使两阶段的最优并行策略显著分叉时，共享配置的损失会超过拼批带来的利用率收益，此时分离式部署的跨池 KV 传输代价反而是值得付的。这条分叉点不靠估算，靠对比两种配置下 $T_{\\text{chunk}}$ 与 $T_{\\text{decode}}$ 的实测比值：若共享配置使其中一项明显劣于各自最优，就应放弃捎带。</p>\n\n\n<h3 id=\"alg-chunked-prefill-piggyback-sec-53\">五十三 · 同族对照：分块捎带在算法谱系中的位置与选用判据</h3>\n\n<p>把分块预填与解码捎带放进同族算法谱系，它夹在两类极端之间：一端是纯连续批处理（FCFS 拼接，长 prefill 直接进批），另一端是分离式预填/解码（Prefill 池与 Decode 池物理隔离，跨池传 KV）。分块捎带本质是“单池内的折中”——用 chunk 切分把 prefill 的独占时间片压到可控量级，同时保留两阶段共享同一前向的算力复用。因此选型的第一判据不是吞吐上限，而是**SLO 形态**：若 TPOT 的 p99 是硬约束、TTFT 可放宽，分块捎带是默认解；若 TTFT 同样是硬约束（如交互式首屏、语音链路），分块捎带会把长 prompt 的排队时间拉长到不可控，此时应转向分离式部署，用独立 Prefill 池吸收长 prompt 的突发。第二判据是**负载水位**：中低负载下单池共享前向的 GPU 利用率明显高于分离式（后者在低负载时 Prefill 池与 Decode 池各自空转），而高负载下分离式可以让两阶段各自用最优 TP/EP 配置，分块捎带则被“共享并行策略”锁死，无法分别调优。</p>\n\n<p>第三判据是模型结构。稠密模型下 chunk 与解码 token 合并只是 GEMM 的 M 维拼接，形状规整；MoE 模型下两者专家分布差异大，合并批次的分组 GEMM 形状更碎，tile 利用率下降会反噬单步前向时间，使 $T_{\\text{iter}}$ 的实际值超出按 chunk token 数估算的预期。此时要么在路由统计上做合并归并（把 prefill chunk 与解码 token 的路由结果统一计数后再分组），要么把 chunk 调大以摊薄碎片开销——但调大又直接顶到 TPOT 上界。这个矛盾构成该方案的规模上限：chunk 切分粒度与 MoE 分组 GEMM 效率共同决定它能撑多大的 EP 拓扑。超长上下文是另一个失效面：chunk 数随 prompt 长度线性增长，调度开销与 KV 页碎片同步上升；若 chunk 边界不与分页边界对齐，页内碎片会吃掉 KV 有效容量，反过来挤压可并发 batch 数，形成“为了 TPOT 切小 chunk、切小后碎片变多、碎片变多后并发下降”的负反馈。</p>\n\n<div class=\"formula\">$$\\text{TPOT}_{\\text{p99}}\\approx \\max_{\\text{iter}}\\left(T_{\\text{decode}}+T_{\\text{chunk}}\\right),\\quad \\text{chunk\\_size}\\le \\frac{\\text{SLO}_{\\text{TPOT}}-T_{\\text{decode}}}{\\text{每 token 时延}}$$</div>\n\n<p>上式的工程含义是：chunk 大小不是自由参数，而是由 TPOT SLO 减去解码前向时间后“剩下的预算”反推出来的上限。取 SLO 允许的最大 chunk 是兼顾吞吐的正解——chunk 越小，prefill 吞吐越低、TTFT 越长，且 MoE 分组 GEMM 越碎；chunk 越大，TPOT 抖动越接近上界、SLO 余量越薄。决策表可按下表落地：</p>\n\n<table class=\"mini\"><thead><tr><th>条件</th><th>选分块捎带</th><th>选连续批处理</th><th>选分离式 P/D</th></tr></thead><tbody><tr><td>TPOT p99 严格、TTFT 可放宽</td><td>首选</td><td>不满足抖动</td><td>可用但成本高</td></tr><tr><td>TTFT 与 TPOT 双硬约束</td><td>长 prompt 排队不可控</td><td>抖动超标</td><td>首选</td></tr><tr><td>中低负载、单池部署</td><td>利用率占优</td><td>抖动大</td><td>两池空转</td></tr><tr><td>高负载、需分阶段独立调 TP/EP</td><td>并行策略被锁死</td><td>抖动大</td><td>首选</td></tr><tr><td>MoE + 大 EP 拓扑</td><td>需合并路由统计，规模受限</td><td>All-to-All 放大阻塞</td><td>跨池 KV 传输成本高</td></tr><tr><td>超长上下文</td><td>chunk 多、页碎片上升</td><td>单次阻塞数十毫秒</td><td>KV 传输量大</td></tr></tbody></table>\n\n<p>落到具体例子：一条长短混合的在线对话链路，批大小由解码队列长度决定，SLO 以 TPOT p99 为主约束。调度器按上式反推 chunk token 数，长 prompt 被切成若干 chunk 逐步捎带，TTFT 被拉长但可预测——这正是它相对纯连续批处理的全部价值：把“数十毫秒的不可预测阻塞”换成“可计算的、有上界的抖动”。反之，若该链路同时要求首 token 在严格时限内返回，长 prompt 请求会在等待队列里排队，排队时间随 chunk 数与队列深度耦合，无法用 chunk 大小单独约束，此时应把长 prompt 分流到独立 Prefill 池。工程判断可以归结为一句：分块捎带是“用 TTFT 换 TPOT 确定性”的交易，交易的汇率由 chunk 大小决定，而 MoE 分组 GEMM 效率与 KV 页对齐是这笔交易的两个隐性手续费——前者决定单步前向能否按预期收敛，后者决定长上下文下并发容量会不会被碎片悄悄吃掉。部署时优先保证 chunk 边界与 KV 分页边界对齐，再在 SLO 预算内把 chunk 取到最大，是这条路线最稳的两个动作。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2023 · NVFP4/FP8权重与激活量化</td></tr><tr><td>解决什么</td><td>连续批处理中长 prefill 会独占 GPU 数十毫秒，期间所有解码请求被阻塞，TPOT 抖动剧烈，MoE 的 Al…</td></tr><tr><td>一句话机制</td><td>把 prefill 切成固定大小的 chunk，每个 iteration 只处理一个 chunk，与当前 batch …</td></tr><tr><td>代价与失效</td><td>chunk 太小则 prefill 吞吐下降，首 token 时延 TTFT 变长；MoE 层 prefill chunk 与解码 tok…</td></tr><tr><td>后继</td><td>量化 MoE 解码融合大核</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-chunked-prefill-piggyback · 共 8 个片段</p>\n";break;}}})();
